     1→/**
     2→ * SeatSniper - Ticket Intelligence Platform
     3→ * Main Entry Point
     4→ */
     5→
     6→import { config } from './config/index.js';
     7→import { logger } from './utils/logger.js';
     8→
     9→// Platform Adapters
    10→import { StubHubAdapter } from './adapters/stubhub/stubhub.adapter.js';
    11→import { TicketmasterAdapter } from './adapters/ticketmaster/ticketmaster.adapter.js';
    12→import { SeatGeekAdapter } from './adapters/seatgeek/seatgeek.adapter.js';
    13→import type { IPlatformAdapter } from './adapters/base/platform-adapter.interface.js';
    14→
    15→// Services
    16→import { ValueEngineService } from './services/value-engine/value-engine.service.js';
    17→
    18→// Notifications
    19→import { TelegramNotifier } from './notifications/telegram/telegram.notifier.js';
    20→import { SMSNotifier } from './notifications/twilio/sms.notifier.js';
    21→import { WhatsAppNotifier } from './notifications/twilio/whatsapp.notifier.js';
    22→import type { INotifier } from './notifications/base/notifier.interface.js';
    23→
    24→// ============================================================================
    25→// Application Class
    26→// ============================================================================
    27→
    28→export class SeatSniperApp {
    29→  private adapters: Map<string, IPlatformAdapter> = new Map();
    30→  private notifiers: Map<string, INotifier> = new Map();
    31→  private valueEngine: ValueEngineService;
    32→  private isRunning: boolean = false;
    33→
    34→  constructor() {
    35→    this.valueEngine = new ValueEngineService();
    36→  }
    37→
    38→  // ==========================================================================
    39→  // Initialization
    40→  // ==========================================================================
    41→
    42→  async initialize(): Promise<void> {
    43→    logger.info('🎯 SeatSniper initializing...');
    44→
    45→    // Initialize platform adapters
    46→    await this.initializeAdapters();
    47→
    48→    // Initialize notification channels
    49→    await this.initializeNotifiers();
    50→
    51→    logger.info('✅ SeatSniper initialized successfully');
    52→  }
    53→
    54→  private async initializeAdapters(): Promise<void> {
    55→    // StubHub
    56→    if (config.stubhub.clientId && config.stubhub.clientSecret) {
    57→      try {
    58→        const stubhub = new StubHubAdapter();
    59→        await stubhub.initialize();
    60→        this.adapters.set('stubhub', stubhub);
    61→        logger.info('  ✓ StubHub adapter ready');
    62→      } catch (error) {
    63→        logger.warn('  ✗ StubHub adapter failed to initialize', {
    64→          error: error instanceof Error ? error.message : 'Unknown error',
    65→        });
    66→      }
    67→    } else {
    68→      logger.info('  - StubHub adapter skipped (no credentials)');
    69→    }
    70→
    71→    // Ticketmaster
    72→    if (config.ticketmaster.apiKey) {
    73→      try {
    74→        const ticketmaster = new TicketmasterAdapter();
    75→        await ticketmaster.initialize();
    76→        this.adapters.set('ticketmaster', ticketmaster);
    77→        logger.info('  ✓ Ticketmaster adapter ready');
    78→      } catch (error) {
    79→        logger.warn('  ✗ Ticketmaster adapter failed to initialize', {
    80→          error: error instanceof Error ? error.message : 'Unknown error',
    81→        });
    82→      }
    83→    } else {
    84→      logger.info('  - Ticketmaster adapter skipped (no credentials)');
    85→    }
    86→
    87→    // SeatGeek
    88→    if (config.seatgeek.clientId) {
    89→      try {
    90→        const seatgeek = new SeatGeekAdapter();
    91→        await seatgeek.initialize();
    92→        this.adapters.set('seatgeek', seatgeek);
    93→        logger.info('  ✓ SeatGeek adapter ready');
    94→      } catch (error) {
    95→        logger.warn('  ✗ SeatGeek adapter failed to initialize', {
    96→          error: error instanceof Error ? error.message : 'Unknown error',
    97→        });
    98→      }
    99→    } else {
   100→      logger.info('  - SeatGeek adapter skipped (no credentials)');
   101→    }
   102→
   103→    if (this.adapters.size === 0) {
   104→      throw new Error('No platform adapters initialized. Check your API credentials.');
   105→    }
   106→  }
   107→
   108→  private async initializeNotifiers(): Promise<void> {
   109→    // Telegram
   110→    if (config.telegram.botToken) {
   111→      try {
   112→        const telegram = new TelegramNotifier();
   113→        await telegram.initialize();
   114→        this.notifiers.set('telegram', telegram);
   115→        logger.info('  ✓ Telegram notifier ready');
   116→      } catch (error) {
   117→        logger.warn('  ✗ Telegram notifier failed to initialize', {
   118→          error: error instanceof Error ? error.message : 'Unknown error',
   119→        });
   120→      }
   121→    } else {
   122→      logger.info('  - Telegram notifier skipped (no bot token)');
   123→    }
   124→
   125→    // SMS
   126→    if (config.twilio.accountSid && config.twilio.authToken) {
   127→      try {
   128→        const sms = new SMSNotifier();
   129→        await sms.initialize();
   130→        this.notifiers.set('sms', sms);
   131→        logger.info('  ✓ SMS notifier ready');
   132→      } catch (error) {
   133→        logger.warn('  ✗ SMS notifier failed to initialize', {
   134→          error: error instanceof Error ? error.message : 'Unknown error',
   135→        });
   136→      }
   137→    } else {
   138→      logger.info('  - SMS notifier skipped (no credentials)');
   139→    }
   140→
   141→    // WhatsApp
   142→    if (config.twilio.accountSid && config.twilio.authToken && config.twilio.whatsappNumber) {
   143→      try {
   144→        const whatsapp = new WhatsAppNotifier();
   145→        await whatsapp.initialize();
   146→        this.notifiers.set('whatsapp', whatsapp);
   147→        logger.info('  ✓ WhatsApp notifier ready');
   148→      } catch (error) {
   149→        logger.warn('  ✗ WhatsApp notifier failed to initialize', {
   150→          error: error instanceof Error ? error.message : 'Unknown error',
   151→        });
   152→      }
   153→    } else {
   154→      logger.info('  - WhatsApp notifier skipped (no WhatsApp number configured)');
   155→    }
   156→
   157→    if (this.notifiers.size === 0) {
   158→      logger.warn('⚠️  No notification channels initialized. Alerts will not be sent.');
   159→    }
   160→  }
   161→
   162→  // ==========================================================================
   163→  // Public API
   164→  // ==========================================================================
   165→
   166→  /**
   167→   * Get available platform adapters
   168→   */
   169→  getAdapters(): Map<string, IPlatformAdapter> {
   170→    return this.adapters;
   171→  }
   172→
   173→  /**
   174→   * Get available notifiers
   175→   */
   176→  getNotifiers(): Map<string, INotifier> {
   177→    return this.notifiers;
   178→  }
   179→
   180→  /**
   181→   * Get the Value Engine service
   182→   */
   183→  getValueEngine(): ValueEngineService {
   184→    return this.valueEngine;
   185→  }
   186→
   187→  /**
   188→   * Check health of all services
   189→   */
   190→  async healthCheck(): Promise<{
   191→    healthy: boolean;
   192→    adapters: Record<string, { healthy: boolean; latency: number }>;
   193→    notifiers: Record<string, boolean>;
   194→  }> {
   195→    const adapterHealth: Record<string, { healthy: boolean; latency: number }> = {};
   196→    const notifierHealth: Record<string, boolean> = {};
   197→
   198→    // Check adapters
   199→    for (const [name, adapter] of this.adapters) {
   200→      const status = await adapter.getHealthStatus();
   201→      adapterHealth[name] = {
   202→        healthy: status.healthy,
   203→        latency: status.latency,
   204→      };
   205→    }
   206→
   207→    // Check notifiers (basic connectivity)
   208→    for (const [name, _notifier] of this.notifiers) {
   209→      notifierHealth[name] = true; // Simplified - could add more checks
   210→    }
   211→
   212→    const allAdaptersHealthy = Object.values(adapterHealth).every(a => a.healthy);
   213→    const hasNotifiers = Object.keys(notifierHealth).length > 0;
   214→
   215→    return {
   216→      healthy: allAdaptersHealthy && hasNotifiers,
   217→      adapters: adapterHealth,
   218→      notifiers: notifierHealth,
   219→    };
   220→  }
   221→
   222→  /**
   223→   * Start the monitoring loop (placeholder for full implementation)
   224→   */
   225→  async start(): Promise<void> {
   226→    if (this.isRunning) {
   227→      logger.warn('SeatSniper is already running');
   228→      return;
   229→    }
   230→
   231→    this.isRunning = true;
   232→    logger.info('🚀 SeatSniper started');
   233→
   234→    // TODO: Implement inventory monitoring loop
   235→    // This would include:
   236→    // 1. Polling events from adapters
   237→    // 2. Scoring listings with ValueEngine
   238→    // 3. Triggering alerts via notifiers
   239→    // 4. Storing data in database
   240→  }
   241→
   242→  /**
   243→   * Stop the monitoring loop
   244→   */
   245→  async stop(): Promise<void> {
   246→    if (!this.isRunning) {
   247→      return;
   248→    }
   249→
   250→    this.isRunning = false;
   251→    logger.info('🛑 SeatSniper stopped');
   252→  }
   253→}
   254→
   255→// ============================================================================
   256→// Main Entry Point
   257→// ============================================================================
   258→
   259→async function main(): Promise<void> {
   260→  logger.info('═══════════════════════════════════════════');
   261→  logger.info('  🎯 SEATSNIPER - Ticket Intelligence');
   262→  logger.info('═══════════════════════════════════════════');
   263→
   264→  const app = new SeatSniperApp();
   265→
   266→  try {
   267→    await app.initialize();
   268→
   269→    // Perform health check
   270→    const health = await app.healthCheck();
   271→    logger.info('Health check:', health);
   272→
   273→    // For now, just log status
   274→    logger.info('🎫 SeatSniper MVP ready!');
   275→    logger.info(`   Adapters: ${[...app.getAdapters().keys()].join(', ') || 'none'}`);
   276→    logger.info(`   Notifiers: ${[...app.getNotifiers().keys()].join(', ') || 'none'}`);
   277→    logger.info(`   Cities: ${config.monitoring.cities.join(', ')}`);
   278→
   279→    // In production, would call app.start() to begin monitoring
   280→
   281→  } catch (error) {
   282→    logger.error('Failed to start SeatSniper', {
   283→      error: error instanceof Error ? error.message : 'Unknown error',
   284→    });
   285→    process.exit(1);
   286→  }
   287→}
   288→
   289→// Run if this is the main module
   290→main().catch(console.error);
   291→

