     1→/**
     2→ * Circuit Breaker and Resilience Utilities
     3→ * Provides fault tolerance patterns for platform API calls
     4→ */
     5→
     6→import {
     7→  CircuitBreakerPolicy,
     8→  ExponentialBackoff,
     9→  retry,
    10→  circuitBreaker,
    11→  bulkhead,
    12→  timeout,
    13→  wrap,
    14→  handleAll,
    15→  ConsecutiveBreaker,
    16→  CircuitState,
    17→} from 'cockatiel';
    18→import { logger } from '../../utils/logger.js';
    19→
    20→// ============================================================================
    21→// Types
    22→// ============================================================================
    23→
    24→export interface ResilienceConfig {
    25→  /** Platform name for logging */
    26→  platformName: string;
    27→
    28→  /** Circuit breaker failure threshold before opening */
    29→  circuitBreakerThreshold?: number;
    30→
    31→  /** Time in ms before attempting to close circuit */
    32→  circuitBreakerHalfOpenAfter?: number;
    33→
    34→  /** Maximum retry attempts */
    35→  maxRetryAttempts?: number;
    36→
    37→  /** Initial retry delay in ms */
    38→  initialRetryDelay?: number;
    39→
    40→  /** Maximum retry delay in ms */
    41→  maxRetryDelay?: number;
    42→
    43→  /** Request timeout in ms */
    44→  timeoutMs?: number;
    45→
    46→  /** Maximum concurrent requests */
    47→  maxConcurrent?: number;
    48→
    49→  /** Queue size for bulkhead */
    50→  queueSize?: number;
    51→}
    52→
    53→export interface ResiliencePolicies {
    54→  /** Combined policy wrapping all resilience patterns */
    55→  policy: ReturnType<typeof wrap>;
    56→
    57→  /** Circuit breaker for monitoring and manual control */
    58→  circuitBreaker: CircuitBreakerPolicy;
    59→
    60→  /** Get current circuit state */
    61→  getCircuitState: () => CircuitState;
    62→
    63→  /** Check if circuit is allowing requests */
    64→  isHealthy: () => boolean;
    65→}
    66→
    67→// ============================================================================
    68→// Default Configuration
    69→// ============================================================================
    70→
    71→const DEFAULT_CONFIG: Required<Omit<ResilienceConfig, 'platformName'>> = {
    72→  circuitBreakerThreshold: 5,
    73→  circuitBreakerHalfOpenAfter: 30_000, // 30 seconds
    74→  maxRetryAttempts: 3,
    75→  initialRetryDelay: 1_000, // 1 second
    76→  maxRetryDelay: 10_000, // 10 seconds
    77→  timeoutMs: 10_000, // 10 seconds
    78→  maxConcurrent: 5,
    79→  queueSize: 10,
    80→};
    81→
    82→// ============================================================================
    83→// Create Resilience Policies
    84→// ============================================================================
    85→
    86→/**
    87→ * Create a set of resilience policies for a platform adapter
    88→ *
    89→ * Policy composition (outer to inner):
    90→ * timeout → retry → circuitBreaker → bulkhead → actual call
    91→ *
    92→ * This means:
    93→ * 1. Overall timeout applies to entire operation including retries
    94→ * 2. Retries happen within the timeout
    95→ * 3. Circuit breaker tracks failures across retries
    96→ * 4. Bulkhead limits concurrent operations
    97→ */
    98→export function createResiliencePolicies(
    99→  config: ResilienceConfig
   100→): ResiliencePolicies {
   101→  const {
   102→    platformName,
   103→    circuitBreakerThreshold = DEFAULT_CONFIG.circuitBreakerThreshold,
   104→    circuitBreakerHalfOpenAfter = DEFAULT_CONFIG.circuitBreakerHalfOpenAfter,
   105→    maxRetryAttempts = DEFAULT_CONFIG.maxRetryAttempts,
   106→    initialRetryDelay = DEFAULT_CONFIG.initialRetryDelay,
   107→    maxRetryDelay = DEFAULT_CONFIG.maxRetryDelay,
   108→    timeoutMs = DEFAULT_CONFIG.timeoutMs,
   109→    maxConcurrent = DEFAULT_CONFIG.maxConcurrent,
   110→    queueSize = DEFAULT_CONFIG.queueSize,
   111→  } = config;
   112→
   113→  // -------------------------------------------------------------------------
   114→  // Circuit Breaker
   115→  // Opens after consecutive failures, half-opens after cooldown
   116→  // -------------------------------------------------------------------------
   117→  const breaker = circuitBreaker(handleAll, {
   118→    halfOpenAfter: circuitBreakerHalfOpenAfter,
   119→    breaker: new ConsecutiveBreaker(circuitBreakerThreshold),
   120→  });
   121→
   122→  // Log circuit state changes
   123→  breaker.onStateChange((state) => {
   124→    const stateNames: Record<CircuitState, string> = {
   125→      [CircuitState.Closed]: 'CLOSED (healthy)',
   126→      [CircuitState.Open]: 'OPEN (failing)',
   127→      [CircuitState.HalfOpen]: 'HALF-OPEN (testing)',
   128→      [CircuitState.Isolated]: 'ISOLATED (manual)',
   129→    };
   130→
   131→    logger.warn(`[${platformName}] Circuit breaker: ${stateNames[state]}`, {
   132→      platform: platformName,
   133→      circuitState: state,
   134→    });
   135→  });
   136→
   137→  breaker.onBreak(() => {
   138→    logger.error(`[${platformName}] Circuit breaker OPENED - stopping requests`, {
   139→      platform: platformName,
   140→    });
   141→  });
   142→
   143→  breaker.onReset(() => {
   144→    logger.info(`[${platformName}] Circuit breaker CLOSED - resuming requests`, {
   145→      platform: platformName,
   146→    });
   147→  });
   148→
   149→  // -------------------------------------------------------------------------
   150→  // Retry with Exponential Backoff + Jitter
   151→  // -------------------------------------------------------------------------
   152→  const retryPolicy = retry(handleAll, {
   153→    maxAttempts: maxRetryAttempts,
   154→    backoff: new ExponentialBackoff({
   155→      initialDelay: initialRetryDelay,
   156→      maxDelay: maxRetryDelay,
   157→      exponent: 2,
   158→    }),
   159→  });
   160→
   161→  retryPolicy.onRetry((event) => {
   162→    logger.warn(`[${platformName}] Retrying request (attempt ${event.attempt})`, {
   163→      platform: platformName,
   164→      attempt: event.attempt,
   165→      delay: event.delay,
   166→      error: event.reason?.message,
   167→    });
   168→  });
   169→
   170→  retryPolicy.onGiveUp((event) => {
   171→    logger.error(`[${platformName}] Giving up after ${event.attempt} attempts`, {
   172→      platform: platformName,
   173→      attempts: event.attempt,
   174→      error: event.reason?.message,
   175→    });
   176→  });
   177→
   178→  // -------------------------------------------------------------------------
   179→  // Bulkhead (Concurrency Limiter)
   180→  // -------------------------------------------------------------------------
   181→  const bulkheadPolicy = bulkhead(maxConcurrent, queueSize);
   182→
   183→  bulkheadPolicy.onReject(() => {
   184→    logger.warn(`[${platformName}] Request rejected by bulkhead (queue full)`, {
   185→      platform: platformName,
   186→    });
   187→  });
   188→
   189→  // -------------------------------------------------------------------------
   190→  // Timeout
   191→  // -------------------------------------------------------------------------
   192→  const timeoutPolicy = timeout(timeoutMs, 'aggressive');
   193→
   194→  timeoutPolicy.onTimeout(() => {
   195→    logger.warn(`[${platformName}] Request timed out after ${timeoutMs}ms`, {
   196→      platform: platformName,
   197→      timeoutMs,
   198→    });
   199→  });
   200→
   201→  // -------------------------------------------------------------------------
   202→  // Compose Policies
   203→  // Order: timeout → retry → circuitBreaker → bulkhead
   204→  // -------------------------------------------------------------------------
   205→  const combinedPolicy = wrap(timeoutPolicy, retryPolicy, breaker, bulkheadPolicy);
   206→
   207→  return {
   208→    policy: combinedPolicy,
   209→    circuitBreaker: breaker,
   210→    getCircuitState: () => breaker.state,
   211→    isHealthy: () => breaker.state === CircuitState.Closed,
   212→  };
   213→}
   214→
   215→// ============================================================================
   216→// Utility Functions
   217→// ============================================================================
   218→
   219→/**
   220→ * Check if an error is a circuit breaker rejection
   221→ */
   222→export function isCircuitBreakerOpen(error: unknown): boolean {
   223→  return (
   224→    error instanceof Error &&
   225→    error.name === 'BrokenCircuitError'
   226→  );
   227→}
   228→
   229→/**
   230→ * Check if an error is a timeout
   231→ */
   232→export function isTimeoutError(error: unknown): boolean {
   233→  return (
   234→    error instanceof Error &&
   235→    error.name === 'TaskCancelledError'
   236→  );
   237→}
   238→
   239→/**
   240→ * Check if an error is a bulkhead rejection
   241→ */
   242→export function isBulkheadRejection(error: unknown): boolean {
   243→  return (
   244→    error instanceof Error &&
   245→    error.name === 'BulkheadRejectedError'
   246→  );
   247→}
   248→
   249→/**
   250→ * Categorize an error for better handling
   251→ */
   252→export function categorizeError(error: unknown): {
   253→  category: 'circuit_open' | 'timeout' | 'bulkhead_full' | 'api_error' | 'unknown';
   254→  retryable: boolean;
   255→  message: string;
   256→} {
   257→  if (isCircuitBreakerOpen(error)) {
   258→    return {
   259→      category: 'circuit_open',
   260→      retryable: false,
   261→      message: 'Circuit breaker is open - platform may be unavailable',
   262→    };
   263→  }
   264→
   265→  if (isTimeoutError(error)) {
   266→    return {
   267→      category: 'timeout',
   268→      retryable: true,
   269→      message: 'Request timed out',
   270→    };
   271→  }
   272→
   273→  if (isBulkheadRejection(error)) {
   274→    return {
   275→      category: 'bulkhead_full',
   276→      retryable: true,
   277→      message: 'Too many concurrent requests - try again later',
   278→    };
   279→  }
   280→
   281→  if (error instanceof Error) {
   282→    return {
   283→      category: 'api_error',
   284→      retryable: false,
   285→      message: error.message,
   286→    };
   287→  }
   288→
   289→  return {
   290→    category: 'unknown',
   291→    retryable: false,
   292→    message: String(error),
   293→  };
   294→}
   295→

