     1→/**
     2→ * Platform Adapter Interface
     3→ * Defines the contract for all ticket platform integrations (StubHub, Ticketmaster, etc.)
     4→ */
     5→
     6→import type { CircuitBreakerPolicy } from 'cockatiel';
     7→
     8→// ============================================================================
     9→// Configuration Types
    10→// ============================================================================
    11→
    12→export interface PlatformConfig {
    13→  name: string;
    14→  baseUrl: string;
    15→  rateLimit: {
    16→    requestsPerMinute?: number;
    17→    requestsPerDay?: number;
    18→  };
    19→  timeout: number;
    20→  retryAttempts: number;
    21→}
    22→
    23→// ============================================================================
    24→// Event Types
    25→// ============================================================================
    26→
    27→export interface EventSearchParams {
    28→  city: string;
    29→  startDate: Date;
    30→  endDate: Date;
    31→  categories?: EventCategory[];
    32→  keyword?: string;
    33→  limit?: number;
    34→}
    35→
    36→export enum EventCategory {
    37→  CONCERTS = 'concerts',
    38→  SPORTS = 'sports',
    39→  THEATER = 'theater',
    40→  COMEDY = 'comedy',
    41→  FESTIVALS = 'festivals',
    42→}
    43→
    44→export interface NormalizedEvent {
    45→  platformId: string;
    46→  platform: Platform;
    47→  name: string;
    48→  venue: {
    49→    id: string;
    50→    name: string;
    51→    city: string;
    52→    state: string;
    53→  };
    54→  dateTime: Date;
    55→  category: EventCategory;
    56→  url: string;
    57→  imageUrl?: string;
    58→  /** Static seat map image URL from platform (if available) */
    59→  seatMapUrl?: string;
    60→}
    61→
    62→// ============================================================================
    63→// Listing Types
    64→// ============================================================================
    65→
    66→export type Platform = 'stubhub' | 'ticketmaster' | 'seatgeek' | 'vividseats';
    67→
    68→export type DeliveryType = 'electronic' | 'instant' | 'physical' | 'willcall';
    69→
    70→export interface NormalizedListing {
    71→  platformListingId: string;
    72→  platform: Platform;
    73→  eventId: string;
    74→  section: string;
    75→  row: string;
    76→  seatNumbers?: string[];
    77→  quantity: number;
    78→  pricePerTicket: number;
    79→  totalPrice: number;
    80→  fees: number;
    81→  deliveryType: DeliveryType;
    82→  sellerRating?: number;
    83→  deepLink: string;
    84→  capturedAt: Date;
    85→}
    86→
    87→// ============================================================================
    88→// Health Check Types
    89→// ============================================================================
    90→
    91→export interface HealthStatus {
    92→  healthy: boolean;
    93→  latency: number;
    94→  lastChecked: Date;
    95→  circuitState?: 'closed' | 'open' | 'half-open';
    96→  errorMessage?: string;
    97→}
    98→
    99→// ============================================================================
   100→// Platform Adapter Interface
   101→// ============================================================================
   102→
   103→export interface IPlatformAdapter {
   104→  /** Platform configuration */
