     2→ * SeatGeek Platform Adapter
     3→ * Integrates with SeatGeek API for event discovery and listings
     4→ */
     5→
     6→import axios from 'axios';
     7→import type { AxiosInstance } from 'axios';
     8→import type { CircuitBreakerPolicy } from 'cockatiel';
     9→import type {
    10→  IPlatformAdapter,
    11→  PlatformConfig,
    12→  EventSearchParams,
    13→  NormalizedEvent,
    14→  NormalizedListing,
    15→  HealthStatus,
    16→} from '../base/platform-adapter.interface.js';
    17→import { createResiliencePolicies, type ResiliencePolicies } from '../base/circuit-breaker.js';
    18→import type {
    19→  SeatGeekResponse,
    20→  SeatGeekEvent,
    21→  SeatGeekListingsResponse,
    22→  SeatGeekSearchParams,
    23→} from './seatgeek.types.js';
    24→import { isSeatGeekError } from './seatgeek.types.js';
    25→import { mapEventsToNormalized, mapListingsToNormalized } from './seatgeek.mapper.js';
    26→import { logger } from '../../utils/logger.js';
    27→import { config } from '../../config/index.js';
    28→
    29→// ============================================================================
    30→// SeatGeek Adapter Implementation
    31→// ============================================================================
    32→
    33→export class SeatGeekAdapter implements IPlatformAdapter {
    34→  readonly config: PlatformConfig = {
    35→    name: 'SeatGeek',
    36→    baseUrl: config.seatgeek.baseUrl,
    37→    rateLimit: {
    38→      requestsPerMinute: config.seatgeek.rateLimit.requestsPerMinute,
    39→    },
    40→    timeout: config.seatgeek.timeout,
    41→    retryAttempts: config.seatgeek.retryAttempts,
    42→  };
    43→
    44→  readonly circuitBreaker: CircuitBreakerPolicy;
    45→
    46→  private resilience: ResiliencePolicies;
    47→  private client: AxiosInstance;
    48→  private isInitialized: boolean = false;
    49→
    50→  constructor() {
    51→    this.resilience = createResiliencePolicies({
    52→      platformName: 'SeatGeek',
    53→      circuitBreakerThreshold: 5,
    54→      circuitBreakerHalfOpenAfter: 30_000,
    55→      maxRetryAttempts: config.seatgeek.retryAttempts,
    56→      timeoutMs: config.seatgeek.timeout,
    57→    });
    58→    this.circuitBreaker = this.resilience.circuitBreaker;
    59→
    60→    this.client = axios.create({
    61→      baseURL: this.config.baseUrl,
    62→      timeout: this.config.timeout,
    63→      headers: {
    64→        Accept: 'application/json',
    65→      },
    66→    });
    67→  }
    68→
    69→  // ==========================================================================
    70→  // Initialization
    71→  // ==========================================================================
    72→
    73→  async initialize(): Promise<void> {
    74→    if (this.isInitialized) return;
    75→
    76→    if (!config.seatgeek.clientId) {
    77→      throw new Error('SeatGeek client ID not configured');
    78→    }
    79→
    80→    try {
    81→      // Test API connectivity with a simple venues query
    82→      const response = await this.client.get('/venues', {
    83→        params: {
    84→          client_id: config.seatgeek.clientId,
    85→          client_secret: config.seatgeek.clientSecret,
    86→          city: 'Portland',
    87→          state: 'OR',
    88→          per_page: 1,
    89→        },
    90→      });
    91→
    92→      if (isSeatGeekError(response.data)) {
    93→        throw new Error(response.data.message);
    94→      }
    95→
    96→      logger.info('[SeatGeek] API connection verified');
    97→      this.isInitialized = true;
    98→    } catch (error) {
    99→      const message = error instanceof Error ? error.message : 'Unknown error';
   100→      throw new Error(`Failed to initialize SeatGeek adapter: ${message}`);
   101→    }
   102→  }
   103→
   104→  // ==========================================================================
   105→  // Event Search
   106→  // ==========================================================================
   107→
   108→  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
   109→    return this.resilience.policy.execute(async () => {
   110→      const searchParams = this.buildSearchParams(params);
   111→
   112→      const response = await this.client.get<SeatGeekResponse<SeatGeekEvent>>(
   113→        '/events',
   114→        { params: searchParams }
   115→      );
   116→
   117→      if (isSeatGeekError(response.data)) {
   118→        throw new Error(response.data.message);
   119→      }
   120→
   121→      const events = response.data.events || [];
   122→
   123→      logger.debug(`[SeatGeek] Found ${events.length} events`, {
   124→        city: params.city,
   125→        total: response.data.meta?.total || 0,
   126→      });
   127→
   128→      return mapEventsToNormalized(events);
   129→    });
   130→  }
   131→
   132→  /**
   133→   * Build SeatGeek search parameters from normalized params
   134→   */
   135→  private buildSearchParams(params: EventSearchParams): SeatGeekSearchParams {
   136→    const searchParams: SeatGeekSearchParams = {
   137→      client_id: config.seatgeek.clientId,
   138→      client_secret: config.seatgeek.clientSecret || undefined,
   139→      'venue.city': params.city,
   140→      'datetime_local.gte': params.startDate.toISOString().split('T')[0],
   141→      'datetime_local.lte': params.endDate.toISOString().split('T')[0],
   142→      per_page: params.limit || 50,
   143→      sort: 'datetime_local',
   144→    };
   145→
   146→    // Map categories to SeatGeek taxonomies
   147→    if (params.categories?.length) {
   148→      const taxonomyMap: Record<string, string> = {
   149→        concerts: 'concert',
   150→        sports: 'sports',
   151→        theater: 'theater',
   152→        comedy: 'comedy',
   153→        festivals: 'concert',
   154→      };
   155→
   156→      const firstCategory = params.categories[0];
   157→      const taxonomy = taxonomyMap[firstCategory];
   158→      if (taxonomy) {
   159→        searchParams['taxonomies.name'] = taxonomy;
   160→      }
   161→    }
   162→
   163→    if (params.keyword) {
   164→      searchParams.q = params.keyword;
   165→    }
   166→
   167→    return searchParams;
   168→  }
   169→
   170→  // ==========================================================================
   171→  // Event Listings
   172→  // ==========================================================================
   173→
   174→  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
   175→    return this.resilience.policy.execute(async () => {
   176→      // SeatGeek listings endpoint
   177→      const response = await this.client.get<SeatGeekListingsResponse>(
   178→        `/events/${platformEventId}/listings`,
   179→        {
   180→          params: {
   181→            client_id: config.seatgeek.clientId,
   182→            client_secret: config.seatgeek.clientSecret || undefined,
   183→          },
   184→        }
   185→      );
   186→
   187→      if (isSeatGeekError(response.data)) {
   188→        throw new Error(response.data.message);
   189→      }
   190→
   191→      const listings = response.data.listings || [];
   192→
   193→      logger.debug(`[SeatGeek] Found ${listings.length} listings for event ${platformEventId}`);
   194→
   195→      return mapListingsToNormalized(listings, platformEventId);
   196→    });
   197→  }
   198→
   199→  // ==========================================================================
   200→  // Venue Seat Map URL
   201→  // ==========================================================================
   202→
   203→  /**
   204→   * Get seat map URL for a venue
   205→   * SeatGeek provides seating chart URLs in venue data
   206→   */
   207→  async getVenueSeatMapUrl(venueId: string): Promise<string | undefined> {
   208→    try {
   209→      const response = await this.client.get(`/venues/${venueId}`, {
   210→        params: {
   211→          client_id: config.seatgeek.clientId,
   212→          client_secret: config.seatgeek.clientSecret || undefined,
   213→        },
   214→      });
   215→
   216→      if (isSeatGeekError(response.data)) {
   217→        return undefined;
   218→      }
   219→
   220→      const venue = response.data;
   221→      return venue.seating_chart_url_large || venue.seating_chart_url;
   222→    } catch {
   223→      return undefined;
   224→    }
   225→  }
   226→
   227→  /**
   228→   * Search for a venue by name and city
   229→   */
   230→  async findVenue(name: string, city: string): Promise<{
   231→    id: string;
   232→    seatMapUrl?: string;
   233→  } | undefined> {
   234→    try {
   235→      const response = await this.client.get('/venues', {
   236→        params: {
   237→          client_id: config.seatgeek.clientId,
   238→          client_secret: config.seatgeek.clientSecret || undefined,
   239→          q: name,
   240→          city,
   241→          per_page: 5,
   242→        },
   243→      });
   244→
   245→      if (isSeatGeekError(response.data)) {
   246→        return undefined;
   247→      }
   248→
   249→      const venues = response.data.venues || [];
   250→      if (venues.length === 0) return undefined;
   251→
   252→      // Find best match
   253→      const normalizedName = name.toLowerCase();
   254→      const match = venues.find((v: { name: string }) =>
   255→        v.name.toLowerCase().includes(normalizedName) ||
   256→        normalizedName.includes(v.name.toLowerCase())
   257→      ) || venues[0];
   258→
   259→      return {
   260→        id: match.id.toString(),
   261→        seatMapUrl: match.seating_chart_url_large || match.seating_chart_url,
   262→      };
   263→    } catch {
   264→      return undefined;
   265→    }
   266→  }
   267→
   268→  // ==========================================================================
   269→  // Health Check
   270→  // ==========================================================================
   271→
   272→  async getHealthStatus(): Promise<HealthStatus> {
   273→    const startTime = Date.now();
   274→
   275→    try {
   276→      const response = await this.client.get('/venues', {
   277→        params: {
   278→          client_id: config.seatgeek.clientId,
   279→          per_page: 1,
   280→        },
   281→        timeout: 5000,
   282→      });
   283→
   284→      const latency = Date.now() - startTime;
   285→
   286→      if (isSeatGeekError(response.data)) {
   287→        return {
   288→          healthy: false,
   289→          latency,
   290→          lastChecked: new Date(),
   291→          errorMessage: response.data.message,
   292→        };
   293→      }
   294→
   295→      return {
   296→        healthy: true,
   297→        latency,
   298→        lastChecked: new Date(),
   299→        circuitState: 'closed',
   300→      };
   301→    } catch (error) {
   302→      return {
   303→        healthy: false,
   304→        latency: Date.now() - startTime,
   305→        lastChecked: new Date(),
   306→        errorMessage: error instanceof Error ? error.message : 'Unknown error',
   307→      };
   308→    }
   309→  }
   310→}
