     1→/**
     2→ * SeatGeek Data Mapper
     3→ * Transforms SeatGeek API responses to normalized types
     4→ */
     5→
     6→import type {
     7→  NormalizedEvent,
     8→  NormalizedListing,
     9→  EventCategory,
    10→  DeliveryType,
    11→} from '../base/platform-adapter.interface.js';
    12→import type {
    13→  SeatGeekEvent,
    14→  SeatGeekListing,
    15→  SeatGeekTaxonomy,
    16→} from './seatgeek.types.js';
    17→import { generateDeepLink } from '../../utils/deep-link-generator.js';
    18→
    19→// ============================================================================
    20→// Event Mapping
    21→// ============================================================================
    22→
    23→/**
    24→ * Map SeatGeek event to normalized event format
    25→ */
    26→export function mapToNormalizedEvent(event: SeatGeekEvent): NormalizedEvent {
    27→  return {
    28→    platformId: event.id.toString(),
    29→    platform: 'seatgeek',
    30→    name: event.title,
    31→    venue: {
    32→      id: event.venue.id.toString(),
    33→      name: event.venue.name,
    34→      city: event.venue.city,
    35→      state: event.venue.state,
    36→    },
    37→    dateTime: new Date(event.datetime_utc),
    38→    category: mapCategory(event.taxonomies),
    39→    url: event.url,
    40→    imageUrl: selectBestImage(event.performers),
    41→    seatMapUrl: event.venue.seating_chart_url_large || event.venue.seating_chart_url,
    42→  };
    43→}
    44→
    45→/**
    46→ * Map SeatGeek taxonomy to normalized category
    47→ */
    48→function mapCategory(taxonomies?: SeatGeekTaxonomy[]): EventCategory {
    49→  if (!taxonomies?.length) {
    50→    return EventCategory.CONCERTS;
    51→  }
    52→
    53→  const names = taxonomies.map(t => t.name.toLowerCase());
    54→
    55→  if (names.some(n => n.includes('concert') || n.includes('music'))) {
    56→    return EventCategory.CONCERTS;
    57→  }
    58→  if (names.some(n => n.includes('sports') || n.includes('nba') ||
    59→      n.includes('nfl') || n.includes('mlb') || n.includes('nhl') ||
    60→      n.includes('mls') || n.includes('soccer'))) {
    61→    return EventCategory.SPORTS;
    62→  }
    63→  if (names.some(n => n.includes('theater') || n.includes('theatre') ||
    64→      n.includes('broadway') || n.includes('musical'))) {
    65→    return EventCategory.THEATER;
    66→  }
    67→  if (names.some(n => n.includes('comedy'))) {
    68→    return EventCategory.COMEDY;
    69→  }
    70→  if (names.some(n => n.includes('festival'))) {
    71→    return EventCategory.FESTIVALS;
    72→  }
    73→
    74→  return EventCategory.CONCERTS;
    75→}
    76→
    77→/**
    78→ * Select best performer image
    79→ */
    80→function selectBestImage(performers?: SeatGeekEvent['performers']): string | undefined {
    81→  if (!performers?.length) return undefined;
    82→
    83→  const primary = performers.find(p => p.primary) || performers[0];
    84→
    85→  // Prefer larger images
    86→  return primary.images?.huge ||
    87→         primary.images?.large ||
    88→         primary.images?.medium ||
    89→         primary.image;
    90→}
    91→
    92→// ============================================================================
    93→// Listing Mapping
    94→// ============================================================================
    95→
    96→/**
    97→ * Map SeatGeek listing to normalized listing format
    98→ */
    99→export function mapToNormalizedListing(
   100→  listing: SeatGeekListing,
   101→  eventId: string
   102→): NormalizedListing {
   103→  return {
   104→    platformListingId: listing.id.toString(),
   105→    platform: 'seatgeek',
   106→    eventId,
   107→    section: listing.section || 'General Admission',
   108→    row: listing.row || '',
   109→    seatNumbers: listing.seat_numbers,
   110→    quantity: listing.quantity,
   111→    pricePerTicket: listing.display_price,
   112→    totalPrice: listing.display_price * listing.quantity,
   113→    fees: 0, // SeatGeek includes fees in display_price
   114→    deliveryType: mapDeliveryType(listing),
   115→    sellerRating: undefined, // SeatGeek doesn't expose seller ratings
   116→    deepLink: generateDeepLink({
   117→      platform: 'seatgeek',
   118→      eventId,
   119→      listingId: listing.id.toString(),
   120→    }),
   121→    capturedAt: new Date(),
   122→  };
   123→}
   124→
   125→/**
   126→ * Map SeatGeek delivery type
   127→ */
   128→function mapDeliveryType(listing: SeatGeekListing): DeliveryType {
   129→  if (listing.instant_delivery) {
   130→    return 'instant';
   131→  }
   132→
   133→  const types = listing.delivery_type?.map(t => t.toLowerCase()) || [];
   134→
   135→  if (types.some(t => t.includes('electronic') || t.includes('mobile'))) {
   136→    return 'electronic';
   137→  }
   138→  if (types.some(t => t.includes('will call'))) {
   139→    return 'willcall';
   140→  }
   141→  if (types.some(t => t.includes('fedex') || t.includes('ups') || t.includes('mail'))) {
   142→    return 'physical';
   143→  }
   144→
   145→  return 'electronic';
   146→}
   147→
   148→// ============================================================================
   149→// Batch Mapping
   150→// ============================================================================
   151→
   152→/**
   153→ * Map array of SeatGeek events to normalized events
   154→ */
   155→export function mapEventsToNormalized(events: SeatGeekEvent[]): NormalizedEvent[] {
   156→  return events.map(mapToNormalizedEvent);
   157→}
   158→
   159→/**
   160→ * Map array of SeatGeek listings to normalized listings
   161→ */
   162→export function mapListingsToNormalized(
   163→  listings: SeatGeekListing[],
   164→  eventId: string
   165→): NormalizedListing[] {
   166→  return listings.map(listing => mapToNormalizedListing(listing, eventId));
   167→}
