   152→  delivery_type: string[];
   153→  listing_type: string;
   154→  is_ga: boolean; // General admission
   155→  resource_uri: string;
   156→  dq_score?: number; // Deal quality score (SeatGeek's value scoring)
   157→  format: string;
   158→  seating_type: string;
   159→  instant_delivery: boolean;
   160→  note?: string;
   161→}
   162→
   163→// ============================================================================
   164→// Search Parameters
   165→// ============================================================================
   166→
   167→export interface SeatGeekSearchParams {
   168→  client_id?: string;
   169→  client_secret?: string;
   170→  q?: string; // Query string
   171→  'venue.city'?: string;
   172→  'venue.state'?: string;
   173→  'venue.country'?: string;
   174→  'venue.id'?: number;
   175→  lat?: number;
   176→  lon?: number;
   177→  range?: string; // e.g., "30mi"
   178→  'datetime_local.gte'?: string;
   179→  'datetime_local.lte'?: string;
