     1→/**
     2→ * StubHub Platform Adapter
     3→ * Implements IPlatformAdapter for StubHub Catalog API
     4→ */
     5→
     6→import axios, { AxiosInstance, AxiosError } from 'axios';
     7→import type { CircuitBreakerPolicy } from 'cockatiel';
     8→import {
     9→  IPlatformAdapter,
    10→  PlatformConfig,
    11→  EventSearchParams,
    12→  NormalizedEvent,
    13→  NormalizedListing,
    14→  HealthStatus,
    15→} from '../base/platform-adapter.interface.js';
    16→import { createResiliencePolicies, type ResiliencePolicies } from '../base/circuit-breaker.js';
    17→import { createMinuteRateLimiter, RateLimiter } from '../../utils/rate-limiter.js';
    18→import { logger, logAdapterOperation } from '../../utils/logger.js';
    19→import { config } from '../../config/index.js';
    20→import type {
    21→  StubHubTokenResponse,
    22→  StubHubEventResponse,
    23→  StubHubListingResponse,
    24→  StubHubSearchParams,
    25→  StubHubListingParams,
    26→} from './stubhub.types.js';
    27→import { mapEventsToNormalized, mapListingsToNormalized } from './stubhub.mapper.js';
    28→
    29→// ============================================================================
    30→// StubHub Adapter Implementation
    31→// ============================================================================
    32→
    33→export class StubHubAdapter implements IPlatformAdapter {
    34→  readonly config: PlatformConfig = {
    35→    name: 'stubhub',
    36→    baseUrl: config.stubhub.baseUrl,
    37→    rateLimit: config.stubhub.rateLimit,
    38→    timeout: config.stubhub.timeout,
    39→    retryAttempts: config.stubhub.retryAttempts,
    40→  };
    41→
    42→  readonly circuitBreaker: CircuitBreakerPolicy;
    43→
    44→  private client: AxiosInstance;
    45→  private rateLimiter: RateLimiter;
    46→  private resilience: ResiliencePolicies;
    47→
    48→  // OAuth state
    49→  private accessToken: string | null = null;
    50→  private tokenExpiry: Date | null = null;
    51→
    52→  constructor() {
    53→    // Initialize resilience policies
    54→    this.resilience = createResiliencePolicies({
    55→      platformName: 'stubhub',
    56→      circuitBreakerThreshold: 5,
    57→      circuitBreakerHalfOpenAfter: 30_000,
    58→      maxRetryAttempts: 3,
    59→      timeoutMs: this.config.timeout,
    60→    });
    61→
    62→    this.circuitBreaker = this.resilience.circuitBreaker;
    63→
    64→    // Initialize rate limiter (10 requests per minute)
    65→    this.rateLimiter = createMinuteRateLimiter(
    66→      this.config.rateLimit.requestsPerMinute || 10
    67→    );
    68→
    69→    // Initialize HTTP client
    70→    this.client = axios.create({
    71→      baseURL: this.config.baseUrl,
    72→      timeout: this.config.timeout,
    73→      headers: {
    74→        'Accept': 'application/json',
    75→        'Content-Type': 'application/json',
    76→      },
    77→    });
    78→  }
    79→
    80→  // ==========================================================================
    81→  // Initialization
    82→  // ==========================================================================
    83→
    84→  async initialize(): Promise<void> {
    85→    logger.info('[StubHub] Initializing adapter...');
    86→
    87→    if (!config.stubhub.clientId || !config.stubhub.clientSecret) {
    88→      throw new Error('StubHub credentials not configured');
    89→    }
    90→
    91→    await this.refreshAccessToken();
    92→    logger.info('[StubHub] Adapter initialized successfully');
    93→  }
    94→
    95→  // ==========================================================================
    96→  // OAuth Token Management
    97→  // ==========================================================================
    98→
    99→  private async refreshAccessToken(): Promise<void> {
   100→    const startTime = Date.now();
   101→
   102→    try {
   103→      const response = await axios.post<StubHubTokenResponse>(
   104→        `${this.config.baseUrl}/sellers/oauth/accesstoken`,
   105→        new URLSearchParams({
   106→          grant_type: 'client_credentials',
   107→          scope: 'read:events',
   108→        }),
   109→        {
   110→          auth: {
   111→            username: config.stubhub.clientId,
   112→            password: config.stubhub.clientSecret,
   113→          },
   114→          headers: {
   115→            'Content-Type': 'application/x-www-form-urlencoded',
   116→          },
   117→          timeout: 10_000,
   118→        }
   119→      );
   120→
   121→      this.accessToken = response.data.access_token;
   122→      // Set expiry to 5 minutes before actual expiry for safety margin
   123→      this.tokenExpiry = new Date(
   124→        Date.now() + (response.data.expires_in - 300) * 1000
   125→      );
   126→
   127→      // Update default authorization header
   128→      this.client.defaults.headers.common['Authorization'] =
   129→        `Bearer ${this.accessToken}`;
   130→
   131→      logAdapterOperation('stubhub', 'token_refresh', startTime, true);
   132→    } catch (error) {
   133→      logAdapterOperation('stubhub', 'token_refresh', startTime, false, {
   134→        error: error instanceof Error ? error.message : 'Unknown error',
   135→      });
   136→      throw new Error(`Failed to refresh StubHub access token: ${error}`);
   137→    }
   138→  }
   139→
   140→  private async ensureValidToken(): Promise<void> {
   141→    // Refresh if no token or expiring within 60 seconds
   142→    if (
   143→      !this.accessToken ||
   144→      !this.tokenExpiry ||
   145→      this.tokenExpiry.getTime() - Date.now() < 60_000
   146→    ) {
   147→      await this.refreshAccessToken();
   148→    }
   149→  }
   150→
   151→  // ==========================================================================
   152→  // Event Search
   153→  // ==========================================================================
   154→
   155→  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
   156→    await this.ensureValidToken();
   157→    await this.rateLimiter.acquire();
   158→
   159→    const startTime = Date.now();
   160→    const searchParams = this.buildSearchParams(params);
   161→
   162→    try {
   163→      const response = await this.resilience.policy.execute(async () => {
   164→        return this.client.get<StubHubEventResponse>('/catalog/events', {
   165→          params: searchParams,
   166→        });
   167→      });
   168→
   169→      const events = mapEventsToNormalized(response.data.events || []);
   170→
   171→      logAdapterOperation('stubhub', 'search_events', startTime, true, {
   172→        city: params.city,
   173→        resultsFound: events.length,
   174→      });
   175→
   176→      return events;
   177→    } catch (error) {
   178→      logAdapterOperation('stubhub', 'search_events', startTime, false, {
   179→        city: params.city,
   180→        error: error instanceof Error ? error.message : 'Unknown error',
   181→      });
   182→      throw this.handleError(error);
   183→    }
   184→  }
   185→
   186→  private buildSearchParams(params: EventSearchParams): StubHubSearchParams {
   187→    const state = config.cityStateMap[params.city.toLowerCase()];
   188→
   189→    return {
   190→      city: params.city,
   191→      state,
   192→      country: 'US',
   193→      minDate: params.startDate.toISOString().split('T')[0],
   194→      maxDate: params.endDate.toISOString().split('T')[0],
   195→      q: params.keyword,
   196→      rows: params.limit || 100,
   197→      sort: 'eventDateLocal asc',
   198→    };
   199→  }
   200→
   201→  // ==========================================================================
   202→  // Event Listings
   203→  // ==========================================================================
   204→
   205→  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
   206→    await this.ensureValidToken();
   207→    await this.rateLimiter.acquire();
   208→
   209→    const startTime = Date.now();
   210→    const listingParams: StubHubListingParams = {
   211→      rows: 250,
   212→      sort: 'price asc',
   213→    };
   214→
   215→    try {
   216→      const response = await this.resilience.policy.execute(async () => {
   217→        return this.client.get<StubHubListingResponse>(
   218→          `/catalog/events/${platformEventId}/listings`,
   219→          { params: listingParams }
   220→        );
   221→      });
   222→
   223→      const listings = mapListingsToNormalized(
   224→        response.data.listings || [],
   225→        platformEventId
   226→      );
   227→
   228→      logAdapterOperation('stubhub', 'get_listings', startTime, true, {
   229→        eventId: platformEventId,
   230→        listingsFound: listings.length,
   231→      });
   232→
   233→      return listings;
   234→    } catch (error) {
   235→      logAdapterOperation('stubhub', 'get_listings', startTime, false, {
   236→        eventId: platformEventId,
   237→        error: error instanceof Error ? error.message : 'Unknown error',
   238→      });
   239→      throw this.handleError(error);
   240→    }
   241→  }
   242→
   243→  // ==========================================================================
   244→  // Health Check
   245→  // ==========================================================================
   246→
   247→  async getHealthStatus(): Promise<HealthStatus> {
   248→    const startTime = Date.now();
   249→
   250→    try {
   251→      await this.ensureValidToken();
   252→
   253→      // Simple health check - search for any event
   254→      await this.client.get('/catalog/events', {
   255→        params: { rows: 1 },
   256→        timeout: 5_000,
   257→      });
   258→
   259→      return {
   260→        healthy: true,
   261→        latency: Date.now() - startTime,
   262→        lastChecked: new Date(),
   263→        circuitState: this.getCircuitState(),
   264→      };
   265→    } catch (error) {
   266→      return {
   267→        healthy: false,
   268→        latency: Date.now() - startTime,
   269→        lastChecked: new Date(),
   270→        circuitState: this.getCircuitState(),
   271→        errorMessage: error instanceof Error ? error.message : 'Unknown error',
   272→      };
   273→    }
   274→  }
   275→
   276→  private getCircuitState(): HealthStatus['circuitState'] {
   277→    const state = this.resilience.getCircuitState();
   278→    // Map cockatiel CircuitState to our simplified state
   279→    if (state === 0) return 'closed';
   280→    if (state === 1) return 'open';
   281→    return 'half-open';
   282→  }
   283→
   284→  // ==========================================================================
   285→  // Error Handling
   286→  // ==========================================================================
   287→
   288→  private handleError(error: unknown): Error {
   289→    if (axios.isAxiosError(error)) {
   290→      const axiosError = error as AxiosError;
   291→
   292→      if (axiosError.response) {
   293→        const status = axiosError.response.status;
   294→
   295→        if (status === 401) {
   296→          // Clear token to force refresh on next request
   297→          this.accessToken = null;
   298→          this.tokenExpiry = null;
   299→          return new Error('StubHub authentication failed - token cleared');
   300→        }
   301→
   302→        if (status === 429) {
   303→          return new Error('StubHub rate limit exceeded');
   304→        }
   305→
   306→        if (status >= 500) {
   307→          return new Error(`StubHub server error: ${status}`);
   308→        }
   309→
   310→        return new Error(
   311→          `StubHub API error: ${status} - ${axiosError.response.statusText}`
   312→        );
   313→      }
   314→
   315→      if (axiosError.code === 'ECONNABORTED') {
   316→        return new Error('StubHub request timed out');
   317→      }
   318→
   319→      return new Error(`StubHub network error: ${axiosError.message}`);
   320→    }
   321→
   322→    if (error instanceof Error) {
   323→      return error;
   324→    }
   325→
   326→    return new Error(`StubHub unknown error: ${String(error)}`);
   327→  }
   328→}
