     1→/**
     2→ * StubHub Data Mapper
     3→ * Transforms StubHub API responses to normalized types
     4→ */
     5→
     6→import type {
     7→  NormalizedEvent,
     8→  NormalizedListing,
     9→  EventCategory,
    10→  DeliveryType,
    11→} from '../base/platform-adapter.interface.js';
    12→import type { StubHubEvent, StubHubListing } from './stubhub.types.js';
    13→import { generateDeepLink } from '../../utils/deep-link-generator.js';
    14→
    15→// ============================================================================
    16→// Event Mapping
    17→// ============================================================================
    18→
    19→/**
    20→ * Map StubHub event to normalized event format
    21→ */
    22→export function mapToNormalizedEvent(event: StubHubEvent): NormalizedEvent {
    23→  return {
    24→    platformId: event.id.toString(),
    25→    platform: 'stubhub',
    26→    name: event.name,
    27→    venue: {
    28→      id: event.venue.id.toString(),
    29→      name: event.venue.name,
    30→      city: event.venue.city,
    31→      state: event.venue.state,
    32→    },
    33→    dateTime: new Date(event.eventDateUTC),
    34→    category: mapCategory(event.ancestors),
    35→    url: `https://www.stubhub.com${event.webURI}`,
    36→    imageUrl: event.imageUrl,
    37→  };
    38→}
    39→
    40→/**
    41→ * Map StubHub category ancestors to normalized category
    42→ */
    43→function mapCategory(ancestors?: StubHubEvent['ancestors']): EventCategory {
    44→  if (!ancestors?.categories?.length) {
    45→    return EventCategory.CONCERTS; // Default
    46→  }
    47→
    48→  const categoryName = ancestors.categories[0].name.toLowerCase();
    49→
    50→  if (categoryName.includes('concert') || categoryName.includes('music')) {
    51→    return EventCategory.CONCERTS;
    52→  }
    53→  if (categoryName.includes('sport') || categoryName.includes('basketball') ||
    54→      categoryName.includes('football') || categoryName.includes('baseball') ||
    55→      categoryName.includes('hockey') || categoryName.includes('soccer')) {
    56→    return EventCategory.SPORTS;
    57→  }
    58→  if (categoryName.includes('theater') || categoryName.includes('theatre') ||
    59→      categoryName.includes('broadway') || categoryName.includes('musical')) {
    60→    return EventCategory.THEATER;
    61→  }
    62→  if (categoryName.includes('comedy') || categoryName.includes('standup')) {
    63→    return EventCategory.COMEDY;
    64→  }
    65→  if (categoryName.includes('festival')) {
    66→    return EventCategory.FESTIVALS;
    67→  }
    68→
    69→  return EventCategory.CONCERTS; // Default fallback
    70→}
    71→
    72→// ============================================================================
    73→// Listing Mapping
    74→// ============================================================================
    75→
    76→/**
    77→ * Map StubHub listing to normalized listing format
    78→ */
    79→export function mapToNormalizedListing(
    80→  listing: StubHubListing,
    81→  eventId: string
    82→): NormalizedListing {
    83→  const section = listing.sectionName || listing.sellerSectionName || 'Unknown';
    84→  const row = listing.row || '';
    85→  const seatNumbers = parseSeatNumbers(listing.seatNumbers);
    86→
    87→  // Calculate total price (StubHub currentPrice is per ticket including fees)
    88→  const pricePerTicket = listing.currentPrice.amount;
    89→  const totalPrice = pricePerTicket * listing.quantity;
    90→
    91→  // Calculate fees (difference between currentPrice and listingPrice if available)
    92→  const fees = listing.listingPrice
    93→    ? (pricePerTicket - listing.listingPrice.amount) * listing.quantity
    94→    : 0;
    95→
    96→  return {
    97→    platformListingId: listing.listingId.toString(),
    98→    platform: 'stubhub',
    99→    eventId,
   100→    section,
   101→    row,
   102→    seatNumbers,
   103→    quantity: listing.quantity,
   104→    pricePerTicket,
   105→    totalPrice,
   106→    fees: Math.max(0, fees),
   107→    deliveryType: mapDeliveryType(listing.deliveryTypeList),
   108→    sellerRating: listing.sellerRating?.rating,
   109→    deepLink: generateDeepLink({
   110→      platform: 'stubhub',
   111→      eventId,
   112→      listingId: listing.listingId.toString(),
   113→      quantity: listing.quantity,
   114→    }),
   115→    capturedAt: new Date(),
   116→  };
   117→}
   118→
   119→/**
   120→ * Parse seat numbers from StubHub format
   121→ * StubHub returns seat numbers as a comma-separated string like "1,2,3"
   122→ */
   123→function parseSeatNumbers(seatStr?: string): string[] | undefined {
   124→  if (!seatStr) return undefined;
   125→
   126→  return seatStr
   127→    .split(',')
   128→    .map(s => s.trim())
   129→    .filter(s => s.length > 0);
   130→}
   131→
   132→/**
   133→ * Map StubHub delivery types to normalized delivery type
   134→ */
   135→function mapDeliveryType(deliveryTypes: string[]): DeliveryType {
   136→  const types = deliveryTypes.map(t => t.toLowerCase());
   137→
   138→  if (types.includes('instant') || types.includes('instant download')) {
   139→    return 'instant';
   140→  }
   141→  if (types.includes('electronic') || types.includes('mobile') ||
   142→      types.includes('mobile ticket') || types.includes('barcode')) {
   143→    return 'electronic';
   144→  }
   145→  if (types.includes('willcall') || types.includes('will call')) {
   146→    return 'willcall';
   147→  }
   148→  if (types.includes('ups') || types.includes('fedex') || types.includes('mail')) {
   149→    return 'physical';
   150→  }
   151→
   152→  return 'electronic'; // Default
   153→}
   154→
   155→// ============================================================================
   156→// Batch Mapping
   157→// ============================================================================
   158→
   159→/**
   160→ * Map array of StubHub events to normalized events
   161→ */
   162→export function mapEventsToNormalized(events: StubHubEvent[]): NormalizedEvent[] {
   163→  return events.map(mapToNormalizedEvent);
   164→}
   165→
   166→/**
   167→ * Map array of StubHub listings to normalized listings
   168→ */
   169→export function mapListingsToNormalized(
   170→  listings: StubHubListing[],
   171→  eventId: string
   172→): NormalizedListing[] {
   173→  return listings.map(listing => mapToNormalizedListing(listing, eventId));
   174→}
