   117→  sectionName?: string;
   118→  zoneId?: number;
   119→  zoneName?: string;
   120→  score?: number;
   121→  dirtyTicketInd?: boolean;
   122→  listingAttributeList?: string[];
   123→  listingAttributeCategoryList?: string[];
   124→  ticketSplit?: string;
   125→  sellerRating?: {
   126→    rating: number;
