   164→
   165→// ============================================================================
   166→// Error Types
   167→// ============================================================================
   168→
   169→export interface StubHubError {
   170→  error: string;
   171→  error_description?: string;
   172→  status?: number;
   173→  code?: string;
   174→}
   175→
   176→export function isStubHubError(data: unknown): data is StubHubError {
   177→  return (
