     1→/**
     2→ * Ticketmaster Platform Adapter
     3→ * Implements IPlatformAdapter for Ticketmaster Discovery API v2
     4→ */
     5→
     6→import axios, { AxiosInstance, AxiosError } from 'axios';
     7→import type { CircuitBreakerPolicy } from 'cockatiel';
     8→import {
     9→  IPlatformAdapter,
    10→  PlatformConfig,
    11→  EventSearchParams,
    12→  NormalizedEvent,
    13→  NormalizedListing,
    14→  HealthStatus,
    15→} from '../base/platform-adapter.interface.js';
    16→import { createResiliencePolicies, type ResiliencePolicies } from '../base/circuit-breaker.js';
    17→import { createDailyRateLimiter, RateLimiter } from '../../utils/rate-limiter.js';
    18→import { logger, logAdapterOperation } from '../../utils/logger.js';
    19→import { config } from '../../config/index.js';
    20→import type {
    21→  TicketmasterPagedResponse,
    22→  TicketmasterEventResponse,
    23→  TicketmasterOffersResponse,
    24→  TicketmasterSearchParams,
    25→} from './ticketmaster.types.js';
    26→import { mapEventsToNormalized, mapOffersToNormalized } from './ticketmaster.mapper.js';
    27→
    28→// ============================================================================
    29→// Ticketmaster Adapter Implementation
    30→// ============================================================================
    31→
    32→export class TicketmasterAdapter implements IPlatformAdapter {
    33→  readonly config: PlatformConfig = {
    34→    name: 'ticketmaster',
    35→    baseUrl: config.ticketmaster.baseUrl,
    36→    rateLimit: config.ticketmaster.rateLimit,
    37→    timeout: config.ticketmaster.timeout,
    38→    retryAttempts: config.ticketmaster.retryAttempts,
    39→  };
    40→
    41→  readonly circuitBreaker: CircuitBreakerPolicy;
    42→
    43→  private client: AxiosInstance;
    44→  private rateLimiter: RateLimiter;
    45→  private resilience: ResiliencePolicies;
    46→
    47→  constructor() {
    48→    // Initialize resilience policies
    49→    this.resilience = createResiliencePolicies({
    50→      platformName: 'ticketmaster',
    51→      circuitBreakerThreshold: 5,
    52→      circuitBreakerHalfOpenAfter: 30_000,
    53→      maxRetryAttempts: 3,
    54→      timeoutMs: this.config.timeout,
    55→    });
    56→
    57→    this.circuitBreaker = this.resilience.circuitBreaker;
    58→
    59→    // Initialize rate limiter (5000 requests per day)
    60→    this.rateLimiter = createDailyRateLimiter(
    61→      this.config.rateLimit.requestsPerDay || 5000
    62→    );
    63→
    64→    // Initialize HTTP client with API key
    65→    this.client = axios.create({
    66→      baseURL: this.config.baseUrl,
    67→      timeout: this.config.timeout,
    68→      params: {
    69→        apikey: config.ticketmaster.apiKey,
    70→      },
    71→      headers: {
    72→        'Accept': 'application/json',
    73→      },
    74→    });
    75→  }
    76→
    77→  // ==========================================================================
    78→  // Initialization
    79→  // ==========================================================================
    80→
    81→  async initialize(): Promise<void> {
    82→    logger.info('[Ticketmaster] Initializing adapter...');
    83→
    84→    if (!config.ticketmaster.apiKey) {
    85→      throw new Error('Ticketmaster API key not configured');
    86→    }
    87→
    88→    // Verify API key with a simple request
    89→    try {
    90→      await this.client.get('/events', { params: { size: 1 } });
    91→      logger.info('[Ticketmaster] Adapter initialized successfully');
    92→    } catch (error) {
    93→      throw new Error(`Failed to initialize Ticketmaster adapter: ${error}`);
    94→    }
    95→  }
    96→
    97→  // ==========================================================================
    98→  // Event Search
    99→  // ==========================================================================
   100→
   101→  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
   102→    await this.rateLimiter.acquire();
   103→
   104→    const startTime = Date.now();
   105→    const searchParams = this.buildSearchParams(params);
   106→
   107→    try {
   108→      const response = await this.resilience.policy.execute(async () => {
   109→        return this.client.get<TicketmasterPagedResponse<TicketmasterEventResponse>>(
   110→          '/events',
   111→          { params: searchParams }
   112→        );
   113→      });
   114→
   115→      const events = mapEventsToNormalized(
   116→        response.data._embedded?.events || []
   117→      );
   118→
   119→      logAdapterOperation('ticketmaster', 'search_events', startTime, true, {
   120→        city: params.city,
   121→        resultsFound: events.length,
   122→        totalAvailable: response.data.page?.totalElements,
   123→      });
   124→
   125→      return events;
   126→    } catch (error) {
   127→      logAdapterOperation('ticketmaster', 'search_events', startTime, false, {
   128→        city: params.city,
   129→        error: error instanceof Error ? error.message : 'Unknown error',
   130→      });
   131→      throw this.handleError(error);
   132→    }
   133→  }
   134→
   135→  private buildSearchParams(params: EventSearchParams): TicketmasterSearchParams {
   136→    const state = config.cityStateMap[params.city.toLowerCase()];
   137→
   138→    // Ticketmaster requires ISO 8601 format with timezone
   139→    const formatDateTime = (date: Date): string => {
   140→      return date.toISOString().replace('.000Z', 'Z');
   141→    };
   142→
   143→    return {
   144→      city: params.city,
   145→      stateCode: state,
   146→      countryCode: 'US',
   147→      startDateTime: formatDateTime(params.startDate),
   148→      endDateTime: formatDateTime(params.endDate),
   149→      keyword: params.keyword,
   150→      size: params.limit || 100,
   151→      sort: 'date,asc',
   152→    };
   153→  }
   154→
   155→  // ==========================================================================
   156→  // Event Listings (Resale Offers)
   157→  // ==========================================================================
   158→
   159→  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
   160→    await this.rateLimiter.acquire();
   161→
   162→    const startTime = Date.now();
   163→
   164→    try {
   165→      // Note: Ticketmaster's resale offers endpoint structure varies
   166→      // This uses the standard Discovery API offers endpoint
   167→      const response = await this.resilience.policy.execute(async () => {
   168→        return this.client.get<TicketmasterOffersResponse>(
   169→          `/events/${platformEventId}/offers`
   170→        );
   171→      });
   172→
   173→      const listings = mapOffersToNormalized(
   174→        response.data.offers || [],
   175→        platformEventId
   176→      );
   177→
   178→      logAdapterOperation('ticketmaster', 'get_listings', startTime, true, {
   179→        eventId: platformEventId,
   180→        listingsFound: listings.length,
   181→      });
   182→
   183→      return listings;
   184→    } catch (error) {
   185→      // 404 is expected if event has no resale offers
   186→      if (axios.isAxiosError(error) && error.response?.status === 404) {
   187→        logAdapterOperation('ticketmaster', 'get_listings', startTime, true, {
   188→          eventId: platformEventId,
   189→          listingsFound: 0,
   190→          note: 'No resale offers available',
   191→        });
   192→        return [];
   193→      }
   194→
   195→      logAdapterOperation('ticketmaster', 'get_listings', startTime, false, {
   196→        eventId: platformEventId,
   197→        error: error instanceof Error ? error.message : 'Unknown error',
   198→      });
   199→      throw this.handleError(error);
   200→    }
   201→  }
   202→
   203→  // ==========================================================================
   204→  // Health Check
   205→  // ==========================================================================
   206→
   207→  async getHealthStatus(): Promise<HealthStatus> {
   208→    const startTime = Date.now();
   209→
   210→    try {
   211→      // Simple health check - search for any event
   212→      await this.client.get('/events', {
   213→        params: { size: 1 },
   214→        timeout: 5_000,
   215→      });
   216→
   217→      return {
   218→        healthy: true,
   219→        latency: Date.now() - startTime,
   220→        lastChecked: new Date(),
   221→        circuitState: this.getCircuitState(),
   222→      };
   223→    } catch (error) {
   224→      return {
   225→        healthy: false,
   226→        latency: Date.now() - startTime,
   227→        lastChecked: new Date(),
   228→        circuitState: this.getCircuitState(),
   229→        errorMessage: error instanceof Error ? error.message : 'Unknown error',
   230→      };
   231→    }
   232→  }
   233→
   234→  private getCircuitState(): HealthStatus['circuitState'] {
   235→    const state = this.resilience.getCircuitState();
   236→    if (state === 0) return 'closed';
   237→    if (state === 1) return 'open';
   238→    return 'half-open';
   239→  }
   240→
   241→  // ==========================================================================
   242→  // Error Handling
   243→  // ==========================================================================
   244→
   245→  private handleError(error: unknown): Error {
   246→    if (axios.isAxiosError(error)) {
   247→      const axiosError = error as AxiosError;
   248→
   249→      if (axiosError.response) {
   250→        const status = axiosError.response.status;
   251→
   252→        if (status === 401) {
   253→          return new Error('Ticketmaster API key is invalid');
   254→        }
   255→
   256→        if (status === 429) {
   257→          return new Error('Ticketmaster rate limit exceeded (5000/day)');
   258→        }
   259→
   260→        if (status === 404) {
   261→          return new Error('Ticketmaster resource not found');
   262→        }
   263→
   264→        if (status >= 500) {
   265→          return new Error(`Ticketmaster server error: ${status}`);
   266→        }
   267→
   268→        // Try to extract error message from response
   269→        const data = axiosError.response.data as { fault?: { faultstring?: string } };
   270→        const message = data?.fault?.faultstring || axiosError.response.statusText;
   271→
   272→        return new Error(`Ticketmaster API error: ${status} - ${message}`);
   273→      }
   274→
   275→      if (axiosError.code === 'ECONNABORTED') {
   276→        return new Error('Ticketmaster request timed out');
   277→      }
   278→
   279→      return new Error(`Ticketmaster network error: ${axiosError.message}`);
   280→    }
   281→
   282→    if (error instanceof Error) {
   283→      return error;
   284→    }
   285→
   286→    return new Error(`Ticketmaster unknown error: ${String(error)}`);
   287→  }
   288→}
