     1→/**
     2→ * Ticketmaster Data Mapper
     3→ * Transforms Ticketmaster API responses to normalized types
     4→ */
     5→
     6→import type {
     7→  NormalizedEvent,
     8→  NormalizedListing,
     9→  EventCategory,
    10→  DeliveryType,
    11→} from '../base/platform-adapter.interface.js';
    12→import type {
    13→  TicketmasterEvent,
    14→  TicketmasterOffer,
    15→  TicketmasterClassification,
    16→} from './ticketmaster.types.js';
    17→import { generateDeepLink } from '../../utils/deep-link-generator.js';
    18→
    19→// ============================================================================
    20→// Event Mapping
    21→// ============================================================================
    22→
    23→/**
    24→ * Map Ticketmaster event to normalized event format
    25→ */
    26→export function mapToNormalizedEvent(event: TicketmasterEvent): NormalizedEvent {
    27→  const venue = event._embedded?.venues?.[0];
    28→
    29→  // Parse datetime - prefer dateTime, fallback to localDate + localTime
    30→  let eventDateTime: Date;
    31→  if (event.dates.start.dateTime) {
    32→    eventDateTime = new Date(event.dates.start.dateTime);
    33→  } else {
    34→    const dateStr = event.dates.start.localDate;
    35→    const timeStr = event.dates.start.localTime || '19:00:00';
    36→    eventDateTime = new Date(`${dateStr}T${timeStr}`);
    37→  }
    38→
    39→  return {
    40→    platformId: event.id,
    41→    platform: 'ticketmaster',
    42→    name: event.name,
    43→    venue: {
    44→      id: venue?.id || 'unknown',
    45→      name: venue?.name || 'Unknown Venue',
    46→      city: venue?.city?.name || 'Unknown',
    47→      state: venue?.state?.stateCode || 'XX',
    48→    },
    49→    dateTime: eventDateTime,
    50→    category: mapCategory(event.classifications),
    51→    url: event.url,
    52→    imageUrl: selectBestImage(event.images),
    53→    seatMapUrl: event.seatmap?.staticUrl,
    54→  };
    55→}
    56→
    57→/**
    58→ * Map Ticketmaster classification to normalized category
    59→ */
    60→function mapCategory(
    61→  classifications?: TicketmasterClassification[]
    62→): EventCategory {
    63→  if (!classifications?.length) {
    64→    return EventCategory.CONCERTS; // Default
    65→  }
    66→
    67→  const primary = classifications.find(c => c.primary) || classifications[0];
    68→  const segmentName = primary.segment?.name?.toLowerCase() || '';
    69→  const genreName = primary.genre?.name?.toLowerCase() || '';
    70→
    71→  if (segmentName === 'music' || genreName.includes('rock') ||
    72→      genreName.includes('pop') || genreName.includes('hip-hop')) {
    73→    return EventCategory.CONCERTS;
    74→  }
    75→  if (segmentName === 'sports') {
    76→    return EventCategory.SPORTS;
    77→  }
    78→  if (segmentName === 'arts & theatre' || genreName.includes('theatre') ||
    79→      genreName.includes('broadway') || genreName.includes('musical')) {
    80→    return EventCategory.THEATER;
    81→  }
    82→  if (genreName.includes('comedy')) {
    83→    return EventCategory.COMEDY;
    84→  }
    85→  if (genreName.includes('festival') || segmentName.includes('festival')) {
    86→    return EventCategory.FESTIVALS;
    87→  }
    88→
    89→  return EventCategory.CONCERTS; // Default fallback
    90→}
    91→
    92→/**
    93→ * Select the best quality image from available images
    94→ */
    95→function selectBestImage(images?: TicketmasterEvent['images']): string | undefined {
    96→  if (!images?.length) return undefined;
    97→
    98→  // Prefer 16_9 ratio, then largest by width
    99→  const preferred = images.find(
   100→    img => img.ratio === '16_9' && (img.width || 0) >= 640
   101→  );
   102→
   103→  if (preferred) return preferred.url;
   104→
   105→  // Sort by width descending and return largest
   106→  const sorted = [...images].sort((a, b) => (b.width || 0) - (a.width || 0));
   107→  return sorted[0]?.url;
   108→}
   109→
   110→// ============================================================================
   111→// Listing/Offer Mapping
   112→// ============================================================================
   113→
   114→/**
   115→ * Map Ticketmaster offer to normalized listing format
   116→ * Note: Ticketmaster offers structure varies between primary and resale
   117→ */
   118→export function mapToNormalizedListing(
   119→  offer: TicketmasterOffer,
   120→  eventId: string
   121→): NormalizedListing {
   122→  // Parse section/row from offer
   123→  const section = offer.section || offer.area?.name || 'Unknown';
   124→  const row = offer.row || '';
   125→  const seatNumbers = offer.seats;
   126→
   127→  // Calculate prices
   128→  const totalPrice = offer.prices?.find(p => p.type === 'total');
   129→  const facePrice = offer.prices?.find(p => p.type === 'face');
   130→  const feePrice = offer.prices?.find(p => p.type === 'fee');
   131→
   132→  const quantity = offer.quantity?.total || 1;
   133→  const pricePerTicket = totalPrice
   134→    ? totalPrice.value / quantity
   135→    : facePrice?.value || 0;
   136→
   137→  return {
   138→    platformListingId: offer.id,
   139→    platform: 'ticketmaster',
   140→    eventId,
   141→    section,
   142→    row,
   143→    seatNumbers,
   144→    quantity,
   145→    pricePerTicket,
   146→    totalPrice: totalPrice?.value || pricePerTicket * quantity,
   147→    fees: feePrice?.value || 0,
   148→    deliveryType: mapDeliveryType(offer.deliveryMethods),
   149→    sellerRating: undefined, // Ticketmaster doesn't provide seller ratings
   150→    deepLink: generateDeepLink({
   151→      platform: 'ticketmaster',
   152→      eventId,
   153→      listingId: offer.id,
   154→    }),
   155→    capturedAt: new Date(),
   156→  };
   157→}
   158→
   159→/**
   160→ * Map Ticketmaster delivery methods to normalized delivery type
   161→ */
   162→function mapDeliveryType(
   163→  methods?: Array<{ type: string; name: string }>
   164→): DeliveryType {
   165→  if (!methods?.length) return 'electronic';
   166→
   167→  const types = methods.map(m => m.type.toLowerCase());
   168→
   169→  if (types.some(t => t.includes('instant') || t.includes('mobile'))) {
   170→    return 'instant';
   171→  }
   172→  if (types.some(t => t.includes('electronic') || t.includes('digital'))) {
   173→    return 'electronic';
   174→  }
   175→  if (types.some(t => t.includes('willcall') || t.includes('will call'))) {
   176→    return 'willcall';
   177→  }
   178→  if (types.some(t => t.includes('mail') || t.includes('ship'))) {
   179→    return 'physical';
   180→  }
   181→
   182→  return 'electronic'; // Default
   183→}
   184→
   185→// ============================================================================
   186→// Batch Mapping
   187→// ============================================================================
   188→
   189→/**
   190→ * Map array of Ticketmaster events to normalized events
   191→ */
   192→export function mapEventsToNormalized(
   193→  events: TicketmasterEvent[]
   194→): NormalizedEvent[] {
   195→  return events.map(mapToNormalizedEvent);
   196→}
   197→
   198→/**
   199→ * Map array of Ticketmaster offers to normalized listings
   200→ * Filters to resale offers only (primary sales are not what we track)
   201→ */
   202→export function mapOffersToNormalized(
   203→  offers: TicketmasterOffer[],
   204→  eventId: string
   205→): NormalizedListing[] {
   206→  return offers
   207→    .filter(offer => offer.type === 'resale')
   208→    .map(offer => mapToNormalizedListing(offer, eventId));
   209→}
   210→

