     1→/**
     2→ * Notifier Interface
     3→ * Defines the contract for all notification channels (Telegram, SMS, WhatsApp)
     4→ */
     5→
     6→import type { Platform } from '../../adapters/base/platform-adapter.interface.js';
     7→
     8→// ============================================================================
     9→// Notification Channel Types
    10→// ============================================================================
    11→
    12→export type NotificationChannel = 'telegram' | 'sms' | 'whatsapp' | 'email';
    13→
    14→// ============================================================================
    15→// Alert Payload Types
    16→// ============================================================================
    17→
    18→export interface TopValueListing {
    19→  rank: number;
    20→  section: string;
    21→  row: string;
    22→  quantity: number;
    23→  pricePerTicket: number;
    24→  valueScore: number;
    25→  recommendation: string;
    26→  deepLink: string;
    27→  platform: Platform;
    28→}
    29→
    30→export interface AlertPayload {
    31→  /** User identifier (Telegram chat ID, phone number, etc.) */
    32→  userId: string;
    33→
    34→  /** Event details */
    35→  eventName: string;
    36→  venueName: string;
    37→  venueCity: string;
    38→  eventDate: Date;
    39→
    40→  /** Top value listings to include in alert */
    41→  listings: TopValueListing[];
    42→
    43→  /** Type of alert */
    44→  alertType: AlertType;
    45→
    46→  /** Optional additional context */
    47→  priceDropPercent?: number;
    48→  previousPrice?: number;
    49→
    50→  /** Seat map URL from platform API (Ticketmaster/SeatGeek) */
    51→  seatMapUrl?: string;
    52→}
    53→
    54→export enum AlertType {
    55→  /** New listing matches user criteria */
    56→  NEW_LISTING = 'new_listing',
    57→
    58→  /** Existing listing dropped in price */
    59→  PRICE_DROP = 'price_drop',
    60→
    61→  /** Exceptional value score detected */
    62→  HIGH_VALUE = 'high_value',
    63→
    64→  /** Periodic digest of top picks */
    65→  DAILY_DIGEST = 'daily_digest',
    66→}
    67→
    68→// ============================================================================
    69→// Notification Result Types
    70→// ============================================================================
    71→
    72→export type DeliveryStatus = 'delivered' | 'pending' | 'failed' | 'unknown';
    73→
    74→export interface NotificationResult {
    75→  success: boolean;
    76→  channel: NotificationChannel;
    77→  messageId?: string;
    78→  error?: string;
    79→  timestamp: Date;
    80→  deliveryStatus: DeliveryStatus;
    81→}
    82→
    83→// ============================================================================
    84→// Notifier Interface
    85→// ============================================================================
    86→
    87→export interface INotifier {
    88→  /** The notification channel this notifier handles */
    89→  readonly channel: NotificationChannel;
    90→
    91→  /**
    92→   * Initialize the notifier (connect to service, validate credentials)
    93→   * @throws Error if initialization fails
    94→   */
    95→  initialize(): Promise<void>;
    96→
    97→  /**
    98→   * Send an alert to a user
    99→   * @param payload The alert content and recipient
   100→   * @returns Result including success status and message ID
   101→   */
   102→  sendAlert(payload: AlertPayload): Promise<NotificationResult>;
   103→
   104→  /**
   105→   * Validate that a recipient identifier is valid
   106→   * @param recipientId User identifier (chat ID, phone number, etc.)
   107→   * @returns True if the recipient is valid and reachable
   108→   */
   109→  validateRecipient(recipientId: string): Promise<boolean>;
   110→
   111→  /**
   112→   * Check the delivery status of a sent message
   113→   * @param messageId The message ID returned from sendAlert
   114→   * @returns Current delivery status
   115→   */
   116→  getDeliveryStatus(messageId: string): Promise<DeliveryStatus>;
   117→}
