     1→/**
     2→ * Telegram Message Formatter
     3→ * Formats alerts for Telegram using MarkdownV2
     4→ */
     5→
     6→import type { AlertPayload, TopValueListing } from '../base/notifier.interface.js';
     7→
     8→// ============================================================================
     9→// Telegram Formatter
    10→// ============================================================================
    11→
    12→export class TelegramFormatter {
    13→  /**
    14→   * Format a full alert message for Telegram
    15→   */
    16→  formatAlert(payload: AlertPayload): string {
    17→    const header = this.formatHeader(payload);
    18→    const listings = payload.listings.map(l => this.formatListing(l)).join('\n\n');
    19→    const footer = this.formatFooter();
    20→
    21→    return `${header}\n\n${listings}${footer}`;
    22→  }
    23→
    24→  /**
    25→   * Format the alert header
    26→   */
    27→  private formatHeader(payload: AlertPayload): string {
    28→    const eventDate = this.formatDate(payload.eventDate);
    29→    const alertIcon = this.getAlertIcon(payload.alertType);
    30→
    31→    return this.escapeMarkdown(
    32→      `${alertIcon} SEATSNIPER ALERT\n` +
    33→      `━━━━━━━━━━━━━━━━━━━━━\n` +
    34→      `🎫 ${payload.eventName}\n` +
    35→      `📍 ${payload.venueName}, ${payload.venueCity}\n` +
    36→      `📅 ${eventDate}\n` +
    37→      `━━━━━━━━━━━━━━━━━━━━━\n` +
    38→      `🔥 TOP ${payload.listings.length} VALUE PICKS:`
    39→    );
    40→  }
    41→
    42→  /**
    43→   * Format a single listing
    44→   */
    45→  private formatListing(listing: TopValueListing): string {
    46→    const platformBadge = this.getPlatformBadge(listing.platform);
    47→    const scoreEmoji = this.getScoreEmoji(listing.valueScore);
    48→
    49→    const details = this.escapeMarkdown(
    50→      `${listing.rank}\\. ${platformBadge} Section ${listing.section}, Row ${listing.row}\n` +
    51→      `   💰 $${listing.pricePerTicket}/ticket \\(${listing.quantity} avail\\)\n` +
    52→      `   ${scoreEmoji} Value Score: ${listing.valueScore}/100\n` +
    53→      `   📊 ${listing.recommendation}`
    54→    );
    55→
    56→    // Deep link is not escaped - Telegram handles URLs specially
    57→    const buyLink = `   [🛒 Buy Now](${listing.deepLink})`;
    58→
    59→    return details + '\n' + buyLink;
    60→  }
    61→
    62→  /**
    63→   * Format the footer
    64→   */
    65→  private formatFooter(): string {
    66→    return '\n\n' + this.escapeMarkdown(
    67→      '━━━━━━━━━━━━━━━━━━━━━\n' +
    68→      '⚠️ Prices subject to change\\. Click links to purchase\\.'
    69→    );
    70→  }
    71→
    72→  /**
    73→   * Format date for display
    74→   */
    75→  private formatDate(date: Date): string {
    76→    return date.toLocaleDateString('en-US', {
    77→      weekday: 'short',
    78→      month: 'short',
    79→      day: 'numeric',
    80→      hour: 'numeric',
    81→      minute: '2-digit',
    82→    });
    83→  }
    84→
    85→  /**
    86→   * Get alert icon based on type
    87→   */
    88→  private getAlertIcon(alertType: string): string {
    89→    const icons: Record<string, string> = {
    90→      new_listing: '🆕',
    91→      price_drop: '📉',
    92→      high_value: '🎯',
    93→      daily_digest: '📋',
    94→    };
    95→    return icons[alertType] || '🎫';
    96→  }
    97→
    98→  /**
    99→   * Get platform badge emoji
   100→   */
   101→  private getPlatformBadge(platform: string): string {
   102→    const badges: Record<string, string> = {
   103→      stubhub: '🟢',      // Green for StubHub
   104→      ticketmaster: '🔵', // Blue for Ticketmaster
   105→      seatgeek: '🟠',     // Orange for SeatGeek
   106→      vividseats: '🟣',   // Purple for Vivid Seats
   107→    };
   108→    return badges[platform] || '⚪';
   109→  }
   110→
   111→  /**
   112→   * Get score emoji based on value
   113→   */
   114→  private getScoreEmoji(score: number): string {
   115→    if (score >= 85) return '🌟';  // Excellent
   116→    if (score >= 70) return '✨';  // Good
   117→    if (score >= 55) return '👍';  // Fair
   118→    return '📊';                   // Below average
   119→  }
   120→
   121→  /**
   122→   * Escape special characters for MarkdownV2
   123→   * Characters: _ * [ ] ( ) ~ ` > # + - = | { } . !
   124→   */
   125→  escapeMarkdown(text: string): string {
   126→    return text.replace(/[_*[\]()~`>#+=|{}.!\\-]/g, '\\$&');
   127→  }
   128→
   129→  /**
   130→   * Format a compact message (for SMS-like brevity)
   131→   */
   132→  formatCompact(payload: AlertPayload): string {
   133→    const topListing = payload.listings[0];
   134→    if (!topListing) return '';
   135→
   136→    return this.escapeMarkdown(
   137→      `🎫 ${payload.eventName}\n` +
   138→      `📍 ${payload.venueName}\n` +
   139→      `💰 $${topListing.pricePerTicket} \\| Score: ${topListing.valueScore}\n`
   140→    ) + `[Buy](${topListing.deepLink})`;
   141→  }
   142→}
