     1→/**
     2→ * Telegram Notifier
     3→ * Sends alerts via Telegram Bot API with seat map visualization
     4→ */
     5→
     6→import { Telegraf } from 'telegraf';
     7→import type {
     8→  INotifier,
     9→  AlertPayload,
    10→  NotificationResult,
    11→  NotificationChannel,
    12→  DeliveryStatus,
    13→} from '../base/notifier.interface.js';
    14→import { TelegramFormatter } from './telegram.formatter.js';
    15→import { SeatMapService } from '../../venues/seat-map.service.js';
    16→import { logger, logAlertDelivery } from '../../utils/logger.js';
    17→import { config } from '../../config/index.js';
    18→
    19→// ============================================================================
    20→// Telegram Notifier Implementation
    21→// ============================================================================
    22→
    23→export class TelegramNotifier implements INotifier {
    24→  readonly channel: NotificationChannel = 'telegram';
    25→
    26→  private bot: Telegraf;
    27→  private formatter: TelegramFormatter;
    28→  private seatMapService: SeatMapService;
    29→  private isInitialized: boolean = false;
    30→
    31→  constructor() {
    32→    this.bot = new Telegraf(config.telegram.botToken);
    33→    this.formatter = new TelegramFormatter();
    34→    this.seatMapService = new SeatMapService();
    35→  }
    36→
    37→  // ==========================================================================
    38→  // Initialization
    39→  // ==========================================================================
    40→
    41→  async initialize(): Promise<void> {
    42→    if (this.isInitialized) return;
    43→
    44→    if (!config.telegram.botToken) {
    45→      throw new Error('Telegram bot token not configured');
    46→    }
    47→
    48→    try {
    49→      // Verify bot token by getting bot info
    50→      const botInfo = await this.bot.telegram.getMe();
    51→      logger.info(`[Telegram] Bot initialized: @${botInfo.username}`, {
    52→        botId: botInfo.id,
    53→        username: botInfo.username,
    54→      });
    55→
    56→      this.isInitialized = true;
    57→    } catch (error) {
    58→      throw new Error(`Failed to initialize Telegram bot: ${error}`);
    59→    }
    60→  }
    61→
    62→  // ==========================================================================
    63→  // Send Alert
    64→  // ==========================================================================
    65→
    66→  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    67→    const startTime = Date.now();
    68→
    69→    try {
    70→      await this.ensureInitialized();
    71→
    72→      // Try to send seat map image first (if available)
    73→      await this.sendSeatMapImage(payload);
    74→
    75→      const message = this.formatter.formatAlert(payload);
    76→
    77→      const result = await this.bot.telegram.sendMessage(
    78→        payload.userId,
    79→        message,
    80→        {
    81→          parse_mode: 'MarkdownV2',
    82→          disable_web_page_preview: false,
    83→        }
    84→      );
    85→
    86→      const latency = Date.now() - startTime;
    87→
    88→      logAlertDelivery(
    89→        'telegram',
    90→        payload.userId,
    91→        true,
    92→        result.message_id.toString()
    93→      );
    94→
    95→      logger.info(`[Telegram] Alert sent successfully`, {
    96→        chatId: payload.userId,
    97→        messageId: result.message_id,
    98→        latency,
    99→        listingsCount: payload.listings.length,
   100→      });
   101→
   102→      return {
   103→        success: true,
   104→        channel: 'telegram',
   105→        messageId: result.message_id.toString(),
   106→        timestamp: new Date(),
   107→        deliveryStatus: 'delivered',
   108→      };
   109→    } catch (error) {
   110→      const latency = Date.now() - startTime;
   111→      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   112→
   113→      logAlertDelivery('telegram', payload.userId, false, undefined, errorMessage);
   114→
   115→      logger.error(`[Telegram] Failed to send alert`, {
   116→        chatId: payload.userId,
   117→        error: errorMessage,
   118→        latency,
   119→      });
   120→
   121→      // Handle specific Telegram errors
   122→      const handled = this.handleTelegramError(error, payload.userId);
   123→
   124→      return {
   125→        success: false,
   126→        channel: 'telegram',
   127→        error: handled.message,
   128→        timestamp: new Date(),
   129→        deliveryStatus: 'failed',
   130→      };
   131→    }
   132→  }
   133→
   134→  // ==========================================================================
   135→  // Seat Map Image Support
   136→  // ==========================================================================
   137→
   138→  /**
   139→   * Send a seat map image before the text alert
   140→   * Tries: 1) Platform API URL (Ticketmaster/SeatGeek), 2) Local highlighted map, 3) Skip
   141→   */
   142→  private async sendSeatMapImage(payload: AlertPayload): Promise<void> {
   143→    try {
   144→      // Check if we can get a seat map (from URL or local)
   145→      if (!this.seatMapService.canGetSeatMap(payload.seatMapUrl, payload.venueName)) {
   146→        logger.debug(`[Telegram] No seat map available for ${payload.venueName}`);
   147→        return;
   148→      }
   149→
   150→      let imageBuffer: Buffer | null = null;
   151→      let mapSource: 'api' | 'local' = 'api';
   152→
   153→      // Strategy 1: Try to fetch from platform API URL (Ticketmaster/SeatGeek)
   154→      if (payload.seatMapUrl) {
   155→        imageBuffer = await this.seatMapService.fetchSeatMapFromUrl(payload.seatMapUrl);
   156→        if (imageBuffer) {
   157→          mapSource = 'api';
   158→        }
   159→      }
   160→
   161→      // Strategy 2: Fall back to local highlighted map (if we have section coordinates)
   162→      if (!imageBuffer && this.seatMapService.hasVenue(payload.venueName)) {
   163→        const sections = payload.listings.slice(0, 5).map((listing, idx) => ({
   164→          sectionName: listing.section,
   165→          rank: idx + 1,
   166→        }));
   167→
   168→        imageBuffer = await this.seatMapService.generateMultiHighlightMap(
   169→          payload.venueName,
   170→          sections
   171→        );
   172→        mapSource = 'local';
   173→      }
   174→
   175→      if (!imageBuffer) {
   176→        logger.debug(`[Telegram] Failed to get seat map for ${payload.venueName}`);
   177→        return;
   178→      }
   179→
   180→      // Build caption with venue info
   181→      const officialMapUrl = this.seatMapService.getOfficialMapUrl(payload.venueName);
   182→      let caption = `🗺️ *${this.formatter.escapeMarkdown(payload.venueName)} Seat Map*\n`;
   183→
   184→      if (mapSource === 'local') {
   185→        caption += `_Highlighted sections show your top deals_\n\n`;
   186→        caption += `🥇 Gold \\= \\#1 Deal  🥈 Silver \\= \\#2  🥉 Bronze \\= \\#3`;
   187→      } else {
   188→        caption += `_Review seating layout before purchase_`;
   189→      }
   190→
   191→      if (officialMapUrl) {
   192→        caption += `\n\n[📍 View Interactive Map](${officialMapUrl})`;
   193→      }
   194→
   195→      // Send the image
   196→      await this.bot.telegram.sendPhoto(
   197→        payload.userId,
   198→        { source: imageBuffer },
   199→        {
   200→          caption,
   201→          parse_mode: 'MarkdownV2',
   202→        }
   203→      );
   204→
   205→      logger.info(`[Telegram] Seat map sent for ${payload.venueName}`, {
   206→        chatId: payload.userId,
   207→        source: mapSource,
   208→      });
   209→    } catch (error) {
   210→      // Non-fatal - log and continue with text alert
   211→      logger.warn(`[Telegram] Failed to send seat map image`, {
   212→        venue: payload.venueName,
   213→        error: error instanceof Error ? error.message : 'Unknown error',
   214→      });
   215→    }
   216→  }
   217→
   218→  // ==========================================================================
   219→  // Recipient Validation
   220→  // ==========================================================================
   221→
   222→  async validateRecipient(chatId: string): Promise<boolean> {
   223→    try {
   224→      await this.ensureInitialized();
   225→
   226→      // Try to get chat info - will fail if bot can't access the chat
   227→      await this.bot.telegram.getChat(chatId);
   228→      return true;
   229→    } catch (error) {
   230→      logger.warn(`[Telegram] Invalid recipient: ${chatId}`, {
   231→        error: error instanceof Error ? error.message : 'Unknown error',
   232→      });
   233→      return false;
   234→    }
   235→  }
   236→
   237→  // ==========================================================================
   238→  // Delivery Status
   239→  // ==========================================================================
   240→
   241→  async getDeliveryStatus(_messageId: string): Promise<DeliveryStatus> {
   242→    // Telegram doesn't provide delivery receipts for bots
   243→    // If sendMessage succeeded, we assume it was delivered
   244→    return 'delivered';
   245→  }
   246→
   247→  // ==========================================================================
   248→  // Private Helpers
   249→  // ==========================================================================
   250→
   251→  private async ensureInitialized(): Promise<void> {
   252→    if (!this.isInitialized) {
   253→      await this.initialize();
   254→    }
   255→  }
   256→
   257→  /**
   258→   * Handle Telegram-specific errors
   259→   */
   260→  private handleTelegramError(
   261→    error: unknown,
   262→    chatId: string
   263→  ): { message: string; shouldDeactivate: boolean } {
   264→    if (!(error instanceof Error)) {
   265→      return { message: 'Unknown error', shouldDeactivate: false };
   266→    }
   267→
   268→    const message = error.message.toLowerCase();
   269→
   270→    // User blocked the bot
   271→    if (message.includes('forbidden') || message.includes('blocked')) {
   272→      logger.warn(`[Telegram] User blocked bot: ${chatId}`);
   273→      return {
   274→        message: 'User has blocked the bot',
   275→        shouldDeactivate: true,
   276→      };
   277→    }
   278→
   279→    // Chat not found (user deleted account or never started chat)
   280→    if (message.includes('chat not found')) {
   281→      logger.warn(`[Telegram] Chat not found: ${chatId}`);
   282→      return {
   283→        message: 'Chat not found - user may have deleted account',
   284→        shouldDeactivate: true,
   285→      };
   286→    }
   287→
   288→    // Rate limited
   289→    if (message.includes('too many requests') || message.includes('429')) {
   290→      logger.warn(`[Telegram] Rate limited`);
   291→      return {
   292→        message: 'Rate limited - will retry later',
   293→        shouldDeactivate: false,
   294→      };
   295→    }
   296→
   297→    // Bad request (malformed message)
   298→    if (message.includes('bad request') || message.includes('400')) {
   299→      logger.error(`[Telegram] Bad request - message may be malformed`);
   300→      return {
   301→        message: 'Invalid message format',
   302→        shouldDeactivate: false,
   303→      };
   304→    }
   305→
   306→    return { message: error.message, shouldDeactivate: false };
   307→  }
   308→
   309→  /**
   310→   * Send a simple text message (for testing)
   311→   */
   312→  async sendTestMessage(chatId: string, text: string): Promise<boolean> {
   313→    try {
   314→      await this.ensureInitialized();
   315→      await this.bot.telegram.sendMessage(chatId, text);
   316→      return true;
   317→    } catch {
   318→      return false;
   319→    }
   320→  }
   321→}
