     1→/**
     2→ * SMS Message Formatter
     3→ * Formats alerts for SMS with character limits in mind
     4→ */
     5→
     6→import type { AlertPayload, TopValueListing } from '../base/notifier.interface.js';
     7→
     8→// ============================================================================
     9→// Constants
    10→// ============================================================================
    11→
    12→const MAX_SMS_LENGTH = 160;  // Single SMS segment
    13→const MAX_TOTAL_LENGTH = 1600; // Maximum total for multi-segment SMS
    14→
    15→// ============================================================================
    16→// SMS Formatter
    17→// ============================================================================
    18→
    19→export class SMSFormatter {
    20→  /**
    21→   * Format a full alert message for SMS
    22→   * Optimized for brevity while maintaining key info
    23→   */
    24→  formatAlert(payload: AlertPayload): string {
    25→    const header = this.formatHeader(payload);
    26→    const topListings = payload.listings.slice(0, 3); // Max 3 listings for SMS
    27→    const listings = topListings.map((l, i) => this.formatListing(l, i + 1)).join('\n');
    28→    const footer = this.formatFooter();
    29→
    30→    const fullMessage = `${header}\n\n${listings}\n\n${footer}`;
    31→
    32→    // Truncate if too long
    33→    if (fullMessage.length > MAX_TOTAL_LENGTH) {
    34→      return this.formatCompact(payload);
    35→    }
    36→
    37→    return fullMessage;
    38→  }
    39→
    40→  /**
    41→   * Format compact header
    42→   */
    43→  private formatHeader(payload: AlertPayload): string {
    44→    const date = this.formatShortDate(payload.eventDate);
    45→
    46→    return (
    47→      `🎫 ${this.truncate(payload.eventName, 40)}\n` +
    48→      `📍 ${payload.venueName}\n` +
    49→      `📅 ${date}`
    50→    );
    51→  }
    52→
    53→  /**
    54→   * Format a single listing (compact)
    55→   */
    56→  private formatListing(listing: TopValueListing, rank: number): string {
    57→    return (
    58→      `${rank}. Sec ${listing.section} Row ${listing.row}\n` +
    59→      `   $${listing.pricePerTicket}/ea | Score: ${listing.valueScore}\n` +
    60→      `   ${listing.deepLink}`
    61→    );
    62→  }
    63→
    64→  /**
    65→   * Format footer
    66→   */
    67→  private formatFooter(): string {
    68→    return 'Reply STOP to unsubscribe';
    69→  }
    70→
    71→  /**
    72→   * Format very compact message (single SMS if possible)
    73→   */
    74→  formatCompact(payload: AlertPayload): string {
    75→    const topListing = payload.listings[0];
    76→    if (!topListing) {
    77→      return `🎫 ${payload.eventName} - No deals found`;
    78→    }
    79→
    80→    const date = this.formatShortDate(payload.eventDate);
    81→
    82→    return (
    83→      `🎫 ${this.truncate(payload.eventName, 30)}\n` +
    84→      `${date} @ ${payload.venueName}\n\n` +
    85→      `TOP: Sec ${topListing.section} $${topListing.pricePerTicket} (Score: ${topListing.valueScore})\n` +
    86→      `${topListing.deepLink}\n\n` +
    87→      `STOP to unsub`
    88→    );
    89→  }
    90→
    91→  /**
    92→   * Format just the essentials (minimal SMS)
    93→   */
    94→  formatMinimal(payload: AlertPayload): string {
    95→    const topListing = payload.listings[0];
    96→    if (!topListing) return '';
    97→
    98→    return (
    99→      `${this.truncate(payload.eventName, 25)} - ` +
   100→      `$${topListing.pricePerTicket} Sec ${topListing.section} Score:${topListing.valueScore} ` +
   101→      `${topListing.deepLink}`
   102→    );
   103→  }
   104→
   105→  /**
   106→   * Format date compactly
   107→   */
   108→  private formatShortDate(date: Date): string {
   109→    return date.toLocaleDateString('en-US', {
   110→      month: 'short',
   111→      day: 'numeric',
   112→      hour: 'numeric',
   113→      minute: '2-digit',
   114→    });
   115→  }
   116→
   117→  /**
   118→   * Truncate text with ellipsis
   119→   */
   120→  private truncate(text: string, maxLength: number): string {
   121→    if (text.length <= maxLength) return text;
   122→    return text.slice(0, maxLength - 3) + '...';
   123→  }
   124→
   125→  /**
   126→   * Count SMS segments for a message
   127→   */
   128→  countSegments(message: string): number {
   129→    // GSM-7 encoding: 160 chars per segment, or 153 for multi-segment
   130→    // Unicode: 70 chars per segment, or 67 for multi-segment
   131→    const hasUnicode = /[^\x00-\x7F]/.test(message);
   132→
   133→    if (hasUnicode) {
   134→      if (message.length <= 70) return 1;
   135→      return Math.ceil(message.length / 67);
   136→    } else {
   137→      if (message.length <= 160) return 1;
   138→      return Math.ceil(message.length / 153);
   139→    }
   140→  }
   141→
   142→  /**
   143→   * Estimate cost for sending this message
   144→   * Based on Twilio rates (~$0.0075 per segment)
   145→   */
   146→  estimateCost(message: string, ratePerSegment: number = 0.0075): number {
   147→    const segments = this.countSegments(message);
   148→    return segments * ratePerSegment;
   149→  }
   150→}
