     1→/**
     2→ * SMS Notifier
     3→ * Sends alerts via Twilio SMS API
     4→ */
     5→
     6→import twilio from 'twilio';
     7→import type { Twilio } from 'twilio';
     8→import type { MessageInstance } from 'twilio/lib/rest/api/v2010/account/message';
     9→import type {
    10→  INotifier,
    11→  AlertPayload,
    12→  NotificationResult,
    13→  NotificationChannel,
    14→  DeliveryStatus,
    15→} from '../base/notifier.interface.js';
    16→import { SMSFormatter } from './sms.formatter.js';
    17→import { logger, logAlertDelivery } from '../../utils/logger.js';
    18→import { config } from '../../config/index.js';
    19→
    20→// ============================================================================
    21→// SMS Notifier Implementation
    22→// ============================================================================
    23→
    24→export class SMSNotifier implements INotifier {
    25→  readonly channel: NotificationChannel = 'sms';
    26→
    27→  private client: Twilio;
    28→  private formatter: SMSFormatter;
    29→  private fromNumber: string;
    30→  private isInitialized: boolean = false;
    31→
    32→  constructor() {
    33→    this.client = twilio(config.twilio.accountSid, config.twilio.authToken);
    34→    this.formatter = new SMSFormatter();
    35→    this.fromNumber = config.twilio.phoneNumber;
    36→  }
    37→
    38→  // ==========================================================================
    39→  // Initialization
    40→  // ==========================================================================
    41→
    42→  async initialize(): Promise<void> {
    43→    if (this.isInitialized) return;
    44→
    45→    if (!config.twilio.accountSid || !config.twilio.authToken) {
    46→      throw new Error('Twilio credentials not configured');
    47→    }
    48→
    49→    if (!config.twilio.phoneNumber) {
    50→      throw new Error('Twilio phone number not configured');
    51→    }
    52→
    53→    try {
    54→      // Verify account by fetching account info
    55→      const account = await this.client.api.accounts(config.twilio.accountSid).fetch();
    56→
    57→      logger.info(`[SMS] Twilio initialized`, {
    58→        accountName: account.friendlyName,
    59→        fromNumber: this.fromNumber,
    60→      });
    61→
    62→      this.isInitialized = true;
    63→    } catch (error) {
    64→      throw new Error(`Failed to initialize Twilio: ${error}`);
    65→    }
    66→  }
    67→
    68→  // ==========================================================================
    69→  // Send Alert
    70→  // ==========================================================================
    71→
    72→  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    73→    const startTime = Date.now();
    74→
    75→    try {
    76→      await this.ensureInitialized();
    77→
    78→      const message = this.formatter.formatAlert(payload);
    79→      const segments = this.formatter.countSegments(message);
    80→
    81→      logger.debug(`[SMS] Sending message`, {
    82→        to: payload.userId,
    83→        length: message.length,
    84→        segments,
    85→        estimatedCost: this.formatter.estimateCost(message),
    86→      });
    87→
    88→      const result: MessageInstance = await this.client.messages.create({
    89→        body: message,
    90→        from: this.fromNumber,
    91→        to: payload.userId,
    92→      });
    93→
    94→      const latency = Date.now() - startTime;
    95→
    96→      logAlertDelivery('sms', payload.userId, true, result.sid);
    97→
    98→      logger.info(`[SMS] Alert sent successfully`, {
    99→        to: payload.userId,
   100→        sid: result.sid,
   101→        status: result.status,
   102→        latency,
   103→        segments,
   104→      });
   105→
   106→      return {
   107→        success: true,
   108→        channel: 'sms',
   109→        messageId: result.sid,
   110→        timestamp: new Date(),
   111→        deliveryStatus: this.mapTwilioStatus(result.status),
   112→      };
   113→    } catch (error) {
   114→      const latency = Date.now() - startTime;
   115→      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   116→
   117→      logAlertDelivery('sms', payload.userId, false, undefined, errorMessage);
   118→
   119→      logger.error(`[SMS] Failed to send alert`, {
   120→        to: payload.userId,
   121→        error: errorMessage,
   122→        latency,
   123→      });
   124→
   125→      // Handle specific Twilio errors
   126→      const handled = this.handleTwilioError(error, payload.userId);
   127→
   128→      return {
   129→        success: false,
   130→        channel: 'sms',
   131→        error: handled.message,
   132→        timestamp: new Date(),
   133→        deliveryStatus: 'failed',
   134→      };
   135→    }
   136→  }
   137→
   138→  // ==========================================================================
   139→  // Recipient Validation
   140→  // ==========================================================================
   141→
   142→  async validateRecipient(phoneNumber: string): Promise<boolean> {
   143→    try {
   144→      await this.ensureInitialized();
   145→
   146→      // Use Twilio Lookup API to validate phone number
   147→      const lookup = await this.client.lookups.v2
   148→        .phoneNumbers(phoneNumber)
   149→        .fetch();
   150→
   151→      return lookup.valid;
   152→    } catch (error) {
   153→      logger.warn(`[SMS] Invalid phone number: ${phoneNumber}`, {
   154→        error: error instanceof Error ? error.message : 'Unknown error',
   155→      });
   156→      return false;
   157→    }
   158→  }
   159→
   160→  // ==========================================================================
   161→  // Delivery Status
   162→  // ==========================================================================
   163→
   164→  async getDeliveryStatus(messageId: string): Promise<DeliveryStatus> {
   165→    try {
   166→      await this.ensureInitialized();
   167→
   168→      const message = await this.client.messages(messageId).fetch();
   169→      return this.mapTwilioStatus(message.status);
   170→    } catch (error) {
   171→      logger.error(`[SMS] Failed to get delivery status`, {
   172→        messageId,
   173→        error: error instanceof Error ? error.message : 'Unknown error',
   174→      });
   175→      return 'unknown';
   176→    }
   177→  }
   178→
   179→  // ==========================================================================
   180→  // Private Helpers
   181→  // ==========================================================================
   182→
   183→  private async ensureInitialized(): Promise<void> {
   184→    if (!this.isInitialized) {
   185→      await this.initialize();
   186→    }
   187→  }
   188→
   189→  /**
   190→   * Map Twilio message status to our DeliveryStatus
   191→   */
   192→  private mapTwilioStatus(status: string): DeliveryStatus {
   193→    const statusMap: Record<string, DeliveryStatus> = {
   194→      delivered: 'delivered',
   195→      sent: 'pending',
   196→      sending: 'pending',
   197→      queued: 'pending',
   198→      accepted: 'pending',
   199→      receiving: 'pending',
   200→      received: 'delivered',
   201→      failed: 'failed',
   202→      undelivered: 'failed',
   203→      canceled: 'failed',
   204→    };
   205→
   206→    return statusMap[status] || 'unknown';
   207→  }
   208→
   209→  /**
   210→   * Handle Twilio-specific errors
   211→   */
   212→  private handleTwilioError(
   213→    error: unknown,
   214→    phoneNumber: string
   215→  ): { message: string; shouldDeactivate: boolean } {
   216→    if (!(error instanceof Error)) {
   217→      return { message: 'Unknown error', shouldDeactivate: false };
   218→    }
   219→
   220→    // Extract Twilio error code if available
   221→    const twilioError = error as { code?: number; message: string };
   222→
   223→    switch (twilioError.code) {
   224→      case 21211: // Invalid phone number
   225→        logger.warn(`[SMS] Invalid phone number: ${phoneNumber}`);
   226→        return {
   227→          message: 'Invalid phone number format',
   228→          shouldDeactivate: true,
   229→        };
   230→
   231→      case 21612: // Unsubscribed
   232→      case 21614: // Unsubscribed
   233→        logger.warn(`[SMS] User unsubscribed: ${phoneNumber}`);
   234→        return {
   235→          message: 'User has unsubscribed from SMS',
   236→          shouldDeactivate: true,
   237→        };
   238→
   239→      case 30003: // Unreachable
   240→        logger.warn(`[SMS] Phone unreachable: ${phoneNumber}`);
   241→        return {
   242→          message: 'Phone number is unreachable',
   243→          shouldDeactivate: false,
   244→        };
   245→
   246→      case 30004: // Blocked by carrier
   247→        logger.warn(`[SMS] Blocked by carrier: ${phoneNumber}`);
   248→        return {
   249→          message: 'Message blocked by carrier',
   250→          shouldDeactivate: false,
   251→        };
   252→
   253→      case 30005: // Unknown destination
   254→        logger.warn(`[SMS] Unknown destination: ${phoneNumber}`);
   255→        return {
   256→          message: 'Unknown phone number',
   257→          shouldDeactivate: true,
   258→        };
   259→
   260→      case 30006: // Landline
   261→        logger.warn(`[SMS] Landline number: ${phoneNumber}`);
   262→        return {
   263→          message: 'Cannot send SMS to landline',
   264→          shouldDeactivate: true,
   265→        };
   266→
   267→      case 20003: // Authentication error
   268→        logger.error(`[SMS] Twilio authentication failed`);
   269→        return {
   270→          message: 'SMS service authentication error',
   271→          shouldDeactivate: false,
   272→        };
   273→
   274→      default:
   275→        return {
   276→          message: twilioError.message,
   277→          shouldDeactivate: false,
   278→        };
   279→    }
   280→  }
   281→
   282→  /**
   283→   * Send a test SMS message
   284→   */
   285→  async sendTestMessage(phoneNumber: string, text: string): Promise<boolean> {
   286→    try {
   287→      await this.ensureInitialized();
   288→
   289→      await this.client.messages.create({
   290→        body: text,
   291→        from: this.fromNumber,
   292→        to: phoneNumber,
   293→      });
   294→
   295→      return true;
   296→    } catch {
   297→      return false;
   298→    }
   299→  }
   300→}
   301→

