   140→
   141→  /**
   142→   * Format template message (for WhatsApp Business API templates)
   143→   * Templates must be pre-approved by WhatsApp
   144→   */
   145→  formatTemplateMessage(payload: AlertPayload): {
   146→    templateName: string;
   147→    parameters: string[];
   148→  } {
   149→    const topListing = payload.listings[0];
   150→
   151→    return {
   152→      templateName: 'ticket_alert',
   153→      parameters: [
   154→        payload.eventName,
   155→        payload.venueName,
   156→        this.formatShortDate(payload.eventDate),
   157→        topListing?.section || 'N/A',
   158→        topListing?.pricePerTicket.toString() || 'N/A',
   159→        topListing?.valueScore.toString() || 'N/A',
   160→        topListing?.deepLink || '',
   161→      ],
   162→    };
   163→  }
   164→
   165→  /**
   166→   * Format date compactly
   167→   */
   168→  private formatShortDate(date: Date): string {
   169→    return date.toLocaleDateString('en-US', {
   170→      month: 'short',
   171→      day: 'numeric',
   172→      hour: 'numeric',
   173→      minute: '2-digit',
   174→    });
   175→  }
   176→
   177→  /**
   178→   * Truncate text with ellipsis
   179→   */
   180→  private truncate(text: string, maxLength: number): string {
   181→    if (text.length <= maxLength) return text;
   182→    return text.slice(0, maxLength - 3) + '...';
   183→  }
   184→}
