     1→/**
     2→ * WhatsApp Notifier
     3→ * Sends alerts via Twilio WhatsApp Business API
     4→ */
     5→
     6→import twilio from 'twilio';
     7→import type { Twilio } from 'twilio';
     8→import type { MessageInstance } from 'twilio/lib/rest/api/v2010/account/message';
     9→import type {
    10→  INotifier,
    11→  AlertPayload,
    12→  NotificationResult,
    13→  NotificationChannel,
    14→  DeliveryStatus,
    15→} from '../base/notifier.interface.js';
    16→import { WhatsAppFormatter } from './whatsapp.formatter.js';
    17→import { logger, logAlertDelivery } from '../../utils/logger.js';
    18→import { config } from '../../config/index.js';
    19→
    20→// ============================================================================
    21→// WhatsApp Notifier Implementation
    22→// ============================================================================
    23→
    24→export class WhatsAppNotifier implements INotifier {
    25→  readonly channel: NotificationChannel = 'whatsapp';
    26→
    27→  private client: Twilio;
    28→  private formatter: WhatsAppFormatter;
    29→  private fromNumber: string;
    30→  private isInitialized: boolean = false;
    31→
    32→  constructor() {
    33→    this.client = twilio(config.twilio.accountSid, config.twilio.authToken);
    34→    this.formatter = new WhatsAppFormatter();
    35→    // WhatsApp numbers must be prefixed with 'whatsapp:'
    36→    this.fromNumber = `whatsapp:${config.twilio.whatsappNumber || config.twilio.phoneNumber}`;
    37→  }
    38→
    39→  // ==========================================================================
    40→  // Initialization
    41→  // ==========================================================================
    42→
    43→  async initialize(): Promise<void> {
    44→    if (this.isInitialized) return;
    45→
    46→    if (!config.twilio.accountSid || !config.twilio.authToken) {
    47→      throw new Error('Twilio credentials not configured');
    48→    }
    49→
    50→    const whatsappNumber = config.twilio.whatsappNumber || config.twilio.phoneNumber;
    51→    if (!whatsappNumber) {
    52→      throw new Error('Twilio WhatsApp number not configured');
    53→    }
    54→
    55→    try {
    56→      // Verify account
    57→      const account = await this.client.api.accounts(config.twilio.accountSid).fetch();
    58→
    59→      logger.info(`[WhatsApp] Twilio WhatsApp initialized`, {
    60→        accountName: account.friendlyName,
    61→        fromNumber: this.fromNumber,
    62→      });
    63→
    64→      this.isInitialized = true;
    65→    } catch (error) {
    66→      throw new Error(`Failed to initialize Twilio WhatsApp: ${error}`);
    67→    }
    68→  }
    69→
    70→  // ==========================================================================
    71→  // Send Alert
    72→  // ==========================================================================
    73→
    74→  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    75→    const startTime = Date.now();
    76→
    77→    try {
    78→      await this.ensureInitialized();
    79→
    80→      const message = this.formatter.formatAlert(payload);
    81→
    82→      // Format recipient with whatsapp: prefix
    83→      const toNumber = this.formatWhatsAppNumber(payload.userId);
    84→
    85→      logger.debug(`[WhatsApp] Sending message`, {
    86→        to: toNumber,
    87→        length: message.length,
    88→      });
    89→
    90→      const result: MessageInstance = await this.client.messages.create({
    91→        body: message,
    92→        from: this.fromNumber,
    93→        to: toNumber,
    94→      });
    95→
    96→      const latency = Date.now() - startTime;
    97→
    98→      logAlertDelivery('whatsapp', payload.userId, true, result.sid);
    99→
   100→      logger.info(`[WhatsApp] Alert sent successfully`, {
   101→        to: payload.userId,
   102→        sid: result.sid,
   103→        status: result.status,
   104→        latency,
   105→      });
   106→
   107→      return {
   108→        success: true,
   109→        channel: 'whatsapp',
   110→        messageId: result.sid,
   111→        timestamp: new Date(),
   112→        deliveryStatus: this.mapTwilioStatus(result.status),
   113→      };
   114→    } catch (error) {
   115→      const latency = Date.now() - startTime;
   116→      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   117→
   118→      logAlertDelivery('whatsapp', payload.userId, false, undefined, errorMessage);
   119→
   120→      logger.error(`[WhatsApp] Failed to send alert`, {
   121→        to: payload.userId,
   122→        error: errorMessage,
   123→        latency,
   124→      });
   125→
   126→      const handled = this.handleWhatsAppError(error, payload.userId);
   127→
   128→      return {
   129→        success: false,
   130→        channel: 'whatsapp',
   131→        error: handled.message,
   132→        timestamp: new Date(),
   133→        deliveryStatus: 'failed',
   134→      };
   135→    }
   136→  }
   137→
   138→  // ==========================================================================
   139→  // Template Messages (for WhatsApp Business API)
   140→  // ==========================================================================
   141→
   142→  /**
   143→   * Send a pre-approved template message
   144→   * Required for initiating conversations with users who haven't messaged first
   145→   */
   146→  async sendTemplateMessage(
   147→    userId: string,
   148→    templateSid: string,
   149→    parameters: Record<string, string>
   150→  ): Promise<NotificationResult> {
   151→    const startTime = Date.now();
   152→
   153→    try {
   154→      await this.ensureInitialized();
   155→
   156→      const toNumber = this.formatWhatsAppNumber(userId);
   157→
   158→      // Build content variables for template
   159→      const contentVariables = JSON.stringify(parameters);
   160→
   161→      const result = await this.client.messages.create({
   162→        from: this.fromNumber,
   163→        to: toNumber,
   164→        contentSid: templateSid,
   165→        contentVariables,
   166→      });
   167→
   168→      const latency = Date.now() - startTime;
   169→
   170→      logger.info(`[WhatsApp] Template message sent`, {
   171→        to: userId,
   172→        sid: result.sid,
   173→        templateSid,
   174→        latency,
   175→      });
   176→
   177→      return {
   178→        success: true,
   179→        channel: 'whatsapp',
   180→        messageId: result.sid,
   181→        timestamp: new Date(),
   182→        deliveryStatus: this.mapTwilioStatus(result.status),
   183→      };
   184→    } catch (error) {
   185→      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   186→
   187→      logger.error(`[WhatsApp] Failed to send template message`, {
   188→        to: userId,
   189→        error: errorMessage,
   190→      });
   191→
   192→      return {
   193→        success: false,
   194→        channel: 'whatsapp',
   195→        error: errorMessage,
   196→        timestamp: new Date(),
   197→        deliveryStatus: 'failed',
   198→      };
   199→    }
   200→  }
   201→
   202→  // ==========================================================================
   203→  // Recipient Validation
   204→  // ==========================================================================
   205→
   206→  async validateRecipient(phoneNumber: string): Promise<boolean> {
   207→    try {
   208→      await this.ensureInitialized();
   209→
   210→      // Use Twilio Lookup API to validate phone number
   211→      const lookup = await this.client.lookups.v2
   212→        .phoneNumbers(phoneNumber)
   213→        .fetch();
   214→
   215→      // WhatsApp requires mobile numbers
   216→      if (!lookup.valid) return false;
   217→
   218→      // Could additionally check if WhatsApp is available on this number
   219→      // using carrier info, but that requires additional API access
   220→
   221→      return true;
   222→    } catch (error) {
   223→      logger.warn(`[WhatsApp] Invalid phone number: ${phoneNumber}`, {
   224→        error: error instanceof Error ? error.message : 'Unknown error',
   225→      });
   226→      return false;
   227→    }
   228→  }
   229→
   230→  // ==========================================================================
   231→  // Delivery Status
   232→  // ==========================================================================
   233→
   234→  async getDeliveryStatus(messageId: string): Promise<DeliveryStatus> {
   235→    try {
   236→      await this.ensureInitialized();
   237→
   238→      const message = await this.client.messages(messageId).fetch();
   239→      return this.mapTwilioStatus(message.status);
   240→    } catch (error) {
   241→      logger.error(`[WhatsApp] Failed to get delivery status`, {
   242→        messageId,
   243→        error: error instanceof Error ? error.message : 'Unknown error',
   244→      });
   245→      return 'unknown';
   246→    }
   247→  }
   248→
   249→  // ==========================================================================
   250→  // Private Helpers
   251→  // ==========================================================================
   252→
   253→  private async ensureInitialized(): Promise<void> {
   254→    if (!this.isInitialized) {
   255→      await this.initialize();
   256→    }
   257→  }
   258→
   259→  /**
   260→   * Format phone number with whatsapp: prefix
   261→   */
   262→  private formatWhatsAppNumber(phoneNumber: string): string {
   263→    // Remove any existing whatsapp: prefix
   264→    const cleaned = phoneNumber.replace(/^whatsapp:/, '');
   265→
   266→    // Ensure E.164 format (starts with +)
   267→    const formatted = cleaned.startsWith('+') ? cleaned : `+${cleaned}`;
   268→
   269→    return `whatsapp:${formatted}`;
   270→  }
   271→
   272→  /**
   273→   * Map Twilio message status to our DeliveryStatus
   274→   */
   275→  private mapTwilioStatus(status: string): DeliveryStatus {
   276→    const statusMap: Record<string, DeliveryStatus> = {
   277→      delivered: 'delivered',
   278→      read: 'delivered',
   279→      sent: 'pending',
   280→      sending: 'pending',
   281→      queued: 'pending',
   282→      accepted: 'pending',
   283→      failed: 'failed',
   284→      undelivered: 'failed',
   285→      canceled: 'failed',
   286→    };
   287→
   288→    return statusMap[status] || 'unknown';
   289→  }
   290→
   291→  /**
   292→   * Handle WhatsApp-specific errors
   293→   */
   294→  private handleWhatsAppError(
   295→    error: unknown,
   296→    phoneNumber: string
   297→  ): { message: string; shouldDeactivate: boolean } {
   298→    if (!(error instanceof Error)) {
   299→      return { message: 'Unknown error', shouldDeactivate: false };
   300→    }
   301→
   302→    const twilioError = error as { code?: number; message: string };
   303→
   304→    switch (twilioError.code) {
   305→      case 21211: // Invalid phone number
   306→        logger.warn(`[WhatsApp] Invalid phone number: ${phoneNumber}`);
   307→        return {
   308→          message: 'Invalid phone number format',
   309→          shouldDeactivate: true,
   310→        };
   311→
   312→      case 21408: // Permission denied (user hasn't opted in)
   313→        logger.warn(`[WhatsApp] User not opted in: ${phoneNumber}`);
   314→        return {
   315→          message: 'User has not opted in to receive WhatsApp messages',
   316→          shouldDeactivate: false,
   317→        };
   318→
   319→      case 21610: // Unsubscribed
   320→        logger.warn(`[WhatsApp] User unsubscribed: ${phoneNumber}`);
   321→        return {
   322→          message: 'User has unsubscribed from WhatsApp messages',
   323→          shouldDeactivate: true,
   324→        };
   325→
   326→      case 63001: // Channel not found
   327→        logger.error(`[WhatsApp] WhatsApp channel not configured`);
   328→        return {
   329→          message: 'WhatsApp channel not properly configured',
   330→          shouldDeactivate: false,
   331→        };
   332→
   333→      case 63003: // Outside of message window
   334→        logger.warn(`[WhatsApp] Outside 24-hour window: ${phoneNumber}`);
   335→        return {
   336→          message: 'Outside 24-hour messaging window - use template message',
   337→          shouldDeactivate: false,
   338→        };
   339→
   340→      case 63007: // Template not found
   341→        logger.error(`[WhatsApp] Message template not found`);
   342→        return {
   343→          message: 'WhatsApp message template not found',
   344→          shouldDeactivate: false,
   345→        };
   346→
   347→      case 63016: // Message failed to send
   348→        return {
   349→          message: 'WhatsApp message failed to send',
   350→          shouldDeactivate: false,
   351→        };
   352→
   353→      default:
   354→        return {
   355→          message: twilioError.message,
   356→          shouldDeactivate: false,
   357→        };
   358→    }
   359→  }
   360→
   361→  /**
   362→   * Send a test WhatsApp message
   363→   */
   364→  async sendTestMessage(phoneNumber: string, text: string): Promise<boolean> {
   365→    try {
   366→      await this.ensureInitialized();
   367→
   368→      const toNumber = this.formatWhatsAppNumber(phoneNumber);
   369→
   370→      await this.client.messages.create({
   371→        body: text,
   372→        from: this.fromNumber,
   373→        to: toNumber,
   374→      });
   375→
   376→      return true;
   377→    } catch {
   378→      return false;
   379→    }
   380→  }
   381→}
