     1→/**
     2→ * Value Engine Service
     3→ * Core service for calculating ticket Value Scores
     4→ */
     5→
     6→import type { NormalizedListing } from '../../adapters/base/platform-adapter.interface.js';
     7→import {
     8→  ValueScoreWeights,
     9→  ValueScoreInput,
    10→  ValueScoreResult,
    11→  ValueRecommendation,
    12→  ScoredListing,
    13→  DEFAULT_WEIGHTS,
    14→  SectionTier,
    15→} from './value-score.types.js';
    16→import { PriceAnalyzer } from './scoring/price-analyzer.js';
    17→import { SectionRanker } from './scoring/section-ranker.js';
    18→import { RowEvaluator } from './scoring/row-evaluator.js';
    19→import { ResalePredictor } from './scoring/resale-predictor.js';
    20→
    21→// ============================================================================
    22→// Value Engine Service
    23→// ============================================================================
    24→
    25→export class ValueEngineService {
    26→  private readonly weights: ValueScoreWeights;
    27→  private readonly priceAnalyzer: PriceAnalyzer;
    28→  private readonly sectionRanker: SectionRanker;
    29→  private readonly rowEvaluator: RowEvaluator;
    30→  private readonly resalePredictor: ResalePredictor;
    31→
    32→  constructor(weights: ValueScoreWeights = DEFAULT_WEIGHTS) {
    33→    // Validate weights sum to 1.0
    34→    const weightSum = Object.values(weights).reduce((a, b) => a + b, 0);
    35→    if (Math.abs(weightSum - 1.0) > 0.001) {
    36→      throw new Error(`Value score weights must sum to 1.0, got ${weightSum}`);
    37→    }
    38→
    39→    this.weights = weights;
    40→    this.priceAnalyzer = new PriceAnalyzer();
    41→    this.sectionRanker = new SectionRanker();
    42→    this.rowEvaluator = new RowEvaluator();
    43→    this.resalePredictor = new ResalePredictor();
    44→  }
    45→
    46→  // ==========================================================================
    47→  // Main Scoring Method
    48→  // ==========================================================================
    49→
    50→  /**
    51→   * Calculate Value Score for a single listing
    52→   */
    53→  calculateValueScore(input: ValueScoreInput): ValueScoreResult {
    54→    // 1. Price vs Average (35%)
    55→    const priceScore = this.priceAnalyzer.analyze(
    56→      input.listing.pricePerTicket,
    57→      input.averagePrice
    58→    );
    59→
    60→    // 2. Section Quality (25%)
    61→    const sectionScore = this.sectionRanker.rank(input.sectionTier);
    62→
    63→    // 3. Row Position (15%)
    64→    const rowScore = this.rowEvaluator.evaluate(
    65→      input.rowRank,
    66→      input.totalRowsInSection
    67→    );
    68→
    69→    // 4. Historical Pricing (15%)
    70→    const historicalScore = this.priceAnalyzer.analyzeHistorical(
    71→      input.listing.pricePerTicket,
    72→      input.historicalPriceData
    73→    );
    74→
    75→    // 5. Resale Potential (10%)
    76→    const resaleScore = this.resalePredictor.predict(
    77→      input.eventPopularity,
    78→      input.daysUntilEvent,
    79→      input.sectionTier
    80→    );
    81→
    82→    // Calculate weighted total
    83→    const totalScore = Math.round(
    84→      priceScore * this.weights.priceVsAverage +
    85→      sectionScore * this.weights.sectionQuality +
    86→      rowScore * this.weights.rowPosition +
    87→      historicalScore * this.weights.historicalPricing +
    88→      resaleScore * this.weights.resalePotential
    89→    );
    90→
    91→    // Clamp to 1-100 range
    92→    const clampedScore = Math.min(100, Math.max(1, totalScore));
    93→
    94→    // Generate result
    95→    const result: ValueScoreResult = {
    96→      totalScore: clampedScore,
    97→      breakdown: {
    98→        priceScore,
    99→        sectionScore,
   100→        rowScore,
   101→        historicalScore,
   102→        resaleScore,
   103→      },
   104→      recommendation: this.getRecommendation(clampedScore),
   105→      reasoning: this.generateReasoning(
   106→        { priceScore, sectionScore, rowScore, historicalScore, resaleScore },
   107→        clampedScore,
   108→        input
   109→      ),
   110→      flags: {
   111→        isHistoricalLow: this.priceAnalyzer.isHistoricalLow(
   112→          input.listing.pricePerTicket,
   113→          input.historicalPriceData
   114→        ),
   115→        isPremiumSection: this.sectionRanker.isPremiumSection(input.sectionTier),
   116→        isFrontRow: this.rowEvaluator.isFrontRow(input.rowRank),
   117→        isPriceOutlier: this.priceAnalyzer.isPriceOutlier(
   118→          input.listing.pricePerTicket,
   119→          input.averagePrice
   120→        ),
   121→      },
   122→    };
   123→
   124→    return result;
   125→  }
   126→
   127→  // ==========================================================================
   128→  // Batch Operations
   129→  // ==========================================================================
   130→
   131→  /**
   132→   * Score multiple listings for an event
   133→   */
   134→  scoreListings(
   135→    listings: NormalizedListing[],
   136→    context: {
   137→      averagePrice: number;
   138→      sectionTiers: Record<string, number>;
   139→      historicalData: Map<string, ValueScoreInput['historicalPriceData']>;
   140→      eventPopularity: number;
   141→      daysUntilEvent: number;
   142→    }
   143→  ): ScoredListing[] {
   144→    return listings.map(listing => {
   145→      const sectionTier = this.sectionRanker.getTierFromSectionName(
   146→        listing.section,
   147→        context.sectionTiers
   148→      );
   149→
   150→      const rowRank = this.rowEvaluator.parseRowToRank(listing.row);
   151→      const totalRows = this.rowEvaluator.estimateTotalRows(sectionTier);
   152→
   153→      const input: ValueScoreInput = {
   154→        listing,
   155→        averagePrice: context.averagePrice,
   156→        sectionAveragePrice: undefined, // Could be enhanced
   157→        sectionTier,
   158→        rowRank: rowRank > 0 ? rowRank : Math.ceil(totalRows / 2), // Default to middle
   159→        totalRowsInSection: totalRows,
   160→        historicalPriceData: context.historicalData.get(listing.section) || [],
   161→        eventPopularity: context.eventPopularity,
   162→        daysUntilEvent: context.daysUntilEvent,
   163→      };
   164→
   165→      return {
   166→        listing,
   167→        score: this.calculateValueScore(input),
   168→      };
   169→    });
   170→  }
   171→
   172→  /**
   173→   * Get top N value picks from scored listings
   174→   */
   175→  getTopValuePicks(
   176→    scoredListings: ScoredListing[],
   177→    limit: number = 10
   178→  ): ScoredListing[] {
   179→    return [...scoredListings]
   180→      .sort((a, b) => b.score.totalScore - a.score.totalScore)
   181→      .slice(0, limit);
   182→  }
   183→
   184→  /**
   185→   * Filter listings by minimum score threshold
   186→   */
   187→  filterByMinScore(
   188→    scoredListings: ScoredListing[],
   189→    minScore: number
   190→  ): ScoredListing[] {
   191→    return scoredListings.filter(sl => sl.score.totalScore >= minScore);
   192→  }
   193→
   194→  // ==========================================================================
   195→  // Utility Methods
   196→  // ==========================================================================
   197→
   198→  /**
   199→   * Calculate average price from listings
   200→   */
   201→  calculateAveragePrice(listings: NormalizedListing[]): number {
   202→    if (listings.length === 0) return 0;
   203→
   204→    const total = listings.reduce((sum, l) => sum + l.pricePerTicket, 0);
   205→    return total / listings.length;
   206→  }
   207→
   208→  /**
   209→   * Get section tier for a listing
   210→   */
   211→  getSectionTier(
   212→    sectionName: string,
   213→    sectionTiers: Record<string, number>
   214→  ): SectionTier {
   215→    return this.sectionRanker.getTierFromSectionName(sectionName, sectionTiers);
   216→  }
   217→
   218→  // ==========================================================================
   219→  // Private Helpers
   220→  // ==========================================================================
   221→
   222→  /**
   223→   * Map total score to recommendation
   224→   */
   225→  private getRecommendation(score: number): ValueRecommendation {
   226→    if (score >= 85) return 'excellent';
   227→    if (score >= 70) return 'good';
   228→    if (score >= 55) return 'fair';
   229→    if (score >= 40) return 'below_average';
   230→    return 'poor';
   231→  }
   232→
   233→  /**
   234→   * Generate human-readable reasoning for the score
   235→   */
   236→  private generateReasoning(
   237→    breakdown: ValueScoreResult['breakdown'],
   238→    totalScore: number,
   239→    input: ValueScoreInput
   240→  ): string {
   241→    const reasons: string[] = [];
   242→
   243→    // Price analysis
   244→    if (breakdown.priceScore >= 75) {
   245→      const percentBelow = Math.round(
   246→        ((input.averagePrice - input.listing.pricePerTicket) / input.averagePrice) * 100
   247→      );
   248→      if (percentBelow > 0) {
   249→        reasons.push(`${percentBelow}% below average price`);
   250→      }
   251→    } else if (breakdown.priceScore <= 40) {
   252→      reasons.push('Above average price');
   253→    }
   254→
   255→    // Section analysis
   256→    if (breakdown.sectionScore >= 80) {
   257→      reasons.push('Premium seating location');
   258→    } else if (breakdown.sectionScore <= 40) {
   259→      reasons.push('Upper level or obstructed view');
   260→    }
   261→
   262→    // Row analysis
   263→    if (breakdown.rowScore >= 90) {
   264→      reasons.push('Front row position');
   265→    }
   266→
   267→    // Historical analysis
   268→    if (breakdown.historicalScore >= 90) {
   269→      reasons.push('Near historical low price');
   270→    }
   271→
   272→    // Resale analysis
   273→    if (breakdown.resaleScore >= 80) {
   274→      reasons.push('High resale potential');
   275→    }
   276→
   277→    // Default reasoning if nothing stands out
   278→    if (reasons.length === 0) {
   279→      if (totalScore >= 70) {
   280→        reasons.push('Solid overall value based on multiple factors');
   281→      } else if (totalScore >= 50) {
   282→        reasons.push('Average value - compare with other options');
   283→      } else {
   284→        reasons.push('Below average value - consider waiting for better deals');
   285→      }
   286→    }
   287→
   288→    return reasons.join('. ') + '.';
   289→  }
   290→}
