     1→/**
     2→ * Price Analyzer
     3→ * Calculates price-based components of the Value Score
     4→ */
     5→
     6→import type { HistoricalPrice } from '../value-score.types.js';
     7→
     8→// ============================================================================
     9→// Price Analyzer
    10→// ============================================================================
    11→
    12→export class PriceAnalyzer {
    13→  /**
    14→   * Analyze price vs current market average
    15→   * Returns score 0-100 where lower price relative to average = higher score
    16→   *
    17→   * Scoring logic:
    18→   * - 50% below average → 100
    19→   * - At average → 50
    20→   * - 50% above average → 0
    21→   */
    22→  analyze(price: number, averagePrice: number): number {
    23→    if (averagePrice <= 0) return 50; // No data, neutral score
    24→
    25→    const priceDifferencePercent = ((averagePrice - price) / averagePrice) * 100;
    26→
    27→    // Map to 0-100 score:
    28→    // Clamped linear mapping from [-50%, +50%] to [0, 100]
    29→    const score = 50 + priceDifferencePercent;
    30→
    31→    return Math.min(100, Math.max(0, Math.round(score)));
    32→  }
    33→
    34→  /**
    35→   * Analyze price vs historical data
    36→   * Returns score 0-100 based on how price compares to historical trends
    37→   *
    38→   * Scoring logic:
    39→   * - At or below all-time low → 100
    40→   * - Between lowest and average → 50-100
    41→   * - At average → 50
    42→   * - Above average → 0-50
    43→   */
    44→  analyzeHistorical(
    45→    currentPrice: number,
    46→    historicalData: HistoricalPrice[]
    47→  ): number {
    48→    if (historicalData.length === 0) return 50; // No data, neutral score
    49→
    50→    // Calculate historical metrics
    51→    const avgHistoricalPrice = this.calculateWeightedAverage(historicalData);
    52→    const lowestHistoricalPrice = this.findLowestPrice(historicalData);
    53→
    54→    // At or below historical low - excellent!
    55→    if (currentPrice <= lowestHistoricalPrice) {
    56→      return 100;
    57→    }
    58→
    59→    // Above historical average - penalize
    60→    if (currentPrice >= avgHistoricalPrice) {
    61→      const overage = (currentPrice - avgHistoricalPrice) / avgHistoricalPrice;
    62→      // Map 0-50% above average to 50-0 score
    63→      return Math.max(0, Math.round(50 - overage * 100));
    64→    }
    65→
    66→    // Between lowest and average - interpolate
    67→    const range = avgHistoricalPrice - lowestHistoricalPrice;
    68→    if (range === 0) return 75; // All prices the same
    69→
    70→    const position = (avgHistoricalPrice - currentPrice) / range;
    71→    // Map position (0 = at average, 1 = at lowest) to (50, 100)
    72→    return Math.round(50 + position * 50);
    73→  }
    74→
    75→  /**
    76→   * Check if price is at or near historical low
    77→   */
    78→  isHistoricalLow(
    79→    currentPrice: number,
    80→    historicalData: HistoricalPrice[],
    81→    threshold: number = 0.05 // 5% tolerance
    82→  ): boolean {
    83→    if (historicalData.length === 0) return false;
    84→
    85→    const lowestPrice = this.findLowestPrice(historicalData);
    86→    return currentPrice <= lowestPrice * (1 + threshold);
    87→  }
    88→
    89→  /**
    90→   * Check if price is significantly below average (outlier)
    91→   */
    92→  isPriceOutlier(
    93→    currentPrice: number,
    94→    averagePrice: number,
    95→    threshold: number = 0.25 // 25% below average
    96→  ): boolean {
    97→    if (averagePrice <= 0) return false;
    98→
    99→    const percentBelow = (averagePrice - currentPrice) / averagePrice;
   100→    return percentBelow >= threshold;
   101→  }
   102→
   103→  // ==========================================================================
   104→  // Private Helpers
   105→  // ==========================================================================
   106→
   107→  /**
   108→   * Calculate weighted average price, giving more weight to recent data
   109→   */
   110→  private calculateWeightedAverage(data: HistoricalPrice[]): number {
   111→    if (data.length === 0) return 0;
   112→
   113→    // Sort by date descending (most recent first)
   114→    const sorted = [...data].sort(
   115→      (a, b) => b.date.getTime() - a.date.getTime()
   116→    );
   117→
   118→    // Apply decay factor - more recent data has more weight
   119→    let weightSum = 0;
   120→    let valueSum = 0;
   121→    const decayFactor = 0.9;
   122→
   123→    sorted.forEach((point, index) => {
   124→      const weight = Math.pow(decayFactor, index);
   125→      weightSum += weight;
   126→      valueSum += point.averagePrice * weight;
   127→    });
   128→
   129→    return valueSum / weightSum;
   130→  }
   131→
   132→  /**
   133→   * Find the lowest recorded price from historical data
   134→   */
   135→  private findLowestPrice(data: HistoricalPrice[]): number {
   136→    if (data.length === 0) return 0;
   137→
   138→    return Math.min(...data.map(d => d.lowestPrice));
   139→  }
   140→}
