     1→/**
     2→ * Resale Predictor
     3→ * Estimates resale potential based on event popularity and timing
     4→ */
     5→
     6→import { SectionTier } from '../value-score.types.js';
     7→
     8→// ============================================================================
     9→// Resale Predictor
    10→// ============================================================================
    11→
    12→export class ResalePredictor {
    13→  /**
    14→   * Predict resale potential and return score (0-100)
    15→   * Higher score = better resale potential
    16→   *
    17→   * Factors:
    18→   * - Event popularity (high demand = easier resale)
    19→   * - Days until event (sweet spot is 7-30 days)
    20→   * - Section tier (premium sections resell better)
    21→   */
    22→  predict(
    23→    eventPopularity: number, // 0-100
    24→    daysUntilEvent: number,
    25→    sectionTier: SectionTier
    26→  ): number {
    27→    // Validate inputs
    28→    const popularity = Math.min(100, Math.max(0, eventPopularity));
    29→    const days = Math.max(0, daysUntilEvent);
    30→
    31→    // Calculate component scores
    32→    const popularityScore = this.scorePopularity(popularity);
    33→    const timingScore = this.scoreTiming(days);
    34→    const sectionScore = this.scoreSection(sectionTier);
    35→
    36→    // Weighted combination
    37→    const weights = {
    38→      popularity: 0.5,
    39→      timing: 0.3,
    40→      section: 0.2,
    41→    };
    42→
    43→    const totalScore =
    44→      popularityScore * weights.popularity +
    45→      timingScore * weights.timing +
    46→      sectionScore * weights.section;
    47→
    48→    return Math.round(totalScore);
    49→  }
    50→
    51→  /**
    52→   * Estimate ROI potential based on current conditions
    53→   * Returns estimated percentage gain/loss
    54→   */
    55→  estimateROI(
    56→    eventPopularity: number,
    57→    daysUntilEvent: number,
    58→    currentPriceVsAverage: number // negative = below avg, positive = above avg
    59→  ): {
    60→    estimatedROI: number;
    61→    confidence: 'high' | 'medium' | 'low';
    62→    recommendation: string;
    63→  } {
    64→    const resaleScore = this.predict(
    65→      eventPopularity,
    66→      daysUntilEvent,
    67→      SectionTier.MID_TIER
    68→    );
    69→
    70→    // Base ROI on resale potential and current price position
    71→    let estimatedROI = 0;
    72→    let confidence: 'high' | 'medium' | 'low' = 'medium';
    73→    let recommendation = '';
    74→
    75→    if (resaleScore >= 80 && currentPriceVsAverage < -15) {
    76→      // High demand event, significantly below average price
    77→      estimatedROI = 20 + Math.abs(currentPriceVsAverage) * 0.5;
    78→      confidence = 'high';
    79→      recommendation = 'Strong resale potential - high demand with good price';
    80→    } else if (resaleScore >= 60 && currentPriceVsAverage < 0) {
    81→      // Moderate demand, below average
    82→      estimatedROI = 10 + Math.abs(currentPriceVsAverage) * 0.3;
    83→      confidence = 'medium';
    84→      recommendation = 'Moderate resale potential';
    85→    } else if (currentPriceVsAverage > 10) {
    86→      // Above average price - risk of loss
    87→      estimatedROI = -currentPriceVsAverage * 0.5;
    88→      confidence = 'medium';
    89→      recommendation = 'Caution - price above average may limit resale';
    90→    } else {
    91→      estimatedROI = 0;
    92→      confidence = 'low';
    93→      recommendation = 'Uncertain resale outcome';
    94→    }
    95→
    96→    return { estimatedROI: Math.round(estimatedROI), confidence, recommendation };
    97→  }
    98→
    99→  // ==========================================================================
   100→  // Private Scoring Functions
   101→  // ==========================================================================
   102→
   103→  /**
   104→   * Score based on event popularity (0-100 input → 0-100 output)
   105→   * Higher popularity = easier to resell
   106→   */
   107→  private scorePopularity(popularity: number): number {
   108→    // Non-linear: very popular events get bonus
   109→    if (popularity >= 90) return 100;
   110→    if (popularity >= 80) return 90;
   111→    if (popularity >= 60) return 70;
   112→    if (popularity >= 40) return 50;
   113→    if (popularity >= 20) return 30;
   114→    return 20;
   115→  }
   116→
   117→  /**
   118→   * Score based on timing relative to event date
   119→   * Sweet spot is 7-30 days (urgency without desperation)
   120→   */
   121→  private scoreTiming(daysUntilEvent: number): number {
   122→    // Too close: buyers are fewer, desperation sales
   123→    if (daysUntilEvent < 1) return 20;
   124→    if (daysUntilEvent < 3) return 40;
   125→    if (daysUntilEvent < 7) return 60;
   126→
   127→    // Sweet spot: 7-30 days
   128→    if (daysUntilEvent <= 30) return 100;
   129→
   130→    // 30-60 days: still good
   131→    if (daysUntilEvent <= 60) return 80;
   132→
   133→    // 60-90 days: okay
   134→    if (daysUntilEvent <= 90) return 60;
   135→
   136→    // Far out: lower urgency from buyers
   137→    if (daysUntilEvent <= 180) return 40;
   138→
   139→    // Very far out
   140→    return 30;
   141→  }
   142→
   143→  /**
   144→   * Score based on section tier
   145→   * Premium sections have better resale value
   146→   */
   147→  private scoreSection(tier: SectionTier): number {
   148→    const tierScores: Record<SectionTier, number> = {
   149→      [SectionTier.PREMIUM]: 100,
   150→      [SectionTier.UPPER_PREMIUM]: 85,
   151→      [SectionTier.MID_TIER]: 70,
   152→      [SectionTier.UPPER_LEVEL]: 50,
   153→      [SectionTier.OBSTRUCTED]: 30,
   154→    };
   155→
   156→    return tierScores[tier] ?? 50;
   157→  }
   158→}
