     1→/**
     2→ * Row Evaluator
     3→ * Evaluates row position within a section
     4→ */
     5→
     6→// ============================================================================
     7→// Row Evaluator
     8→// ============================================================================
     9→
    10→export class RowEvaluator {
    11→  /**
    12→   * Evaluate row position and return score (0-100)
    13→   * Front rows score higher than back rows
    14→   *
    15→   * @param rowRank Position of this row (1 = front row)
    16→   * @param totalRows Total rows in the section
    17→   */
    18→  evaluate(rowRank: number, totalRows: number): number {
    19→    // Handle edge cases
    20→    if (totalRows <= 0) return 50; // No data
    21→    if (rowRank <= 0) return 50; // Invalid input
    22→    if (rowRank > totalRows) rowRank = totalRows; // Cap at max
    23→
    24→    // Front row always gets 100
    25→    if (rowRank === 1) return 100;
    26→
    27→    // Calculate position percentage (0 = front, 1 = back)
    28→    const position = (rowRank - 1) / (totalRows - 1);
    29→
    30→    // Non-linear scoring: front rows are disproportionately better
    31→    // Use square root to give more value to front positions
    32→    const score = 100 - Math.sqrt(position) * 80;
    33→
    34→    return Math.round(Math.max(20, score));
    35→  }
    36→
    37→  /**
    38→   * Parse row string to numeric rank
    39→   * Handles both numeric ("15") and alphabetic ("K") rows
    40→   */
    41→  parseRowToRank(row: string): number {
    42→    if (!row || row.trim() === '') return -1;
    43→
    44→    const trimmed = row.trim().toUpperCase();
    45→
    46→    // Check for numeric row
    47→    const numericMatch = trimmed.match(/^(\d+)$/);
    48→    if (numericMatch) {
    49→      return parseInt(numericMatch[1], 10);
    50→    }
    51→
    52→    // Check for single letter row (A=1, B=2, etc.)
    53→    const letterMatch = trimmed.match(/^([A-Z])$/);
    54→    if (letterMatch) {
    55→      return letterMatch[1].charCodeAt(0) - 'A'.charCodeAt(0) + 1;
    56→    }
    57→
    58→    // Check for double letter row (AA=27, AB=28, etc.)
    59→    const doubleLetterMatch = trimmed.match(/^([A-Z])([A-Z])$/);
    60→    if (doubleLetterMatch) {
    61→      const first = doubleLetterMatch[1].charCodeAt(0) - 'A'.charCodeAt(0);
    62→      const second = doubleLetterMatch[2].charCodeAt(0) - 'A'.charCodeAt(0) + 1;
    63→      return 26 + first * 26 + second;
    64→    }
    65→
    66→    // Handle special rows
    67→    if (trimmed === 'GA' || trimmed === 'GENERAL ADMISSION') {
    68→      return 1; // GA is typically good
    69→    }
    70→    if (trimmed === 'PIT') {
    71→      return 1; // Pit is front
    72→    }
    73→
    74→    // Unknown format
    75→    return -1;
    76→  }
    77→
    78→  /**
    79→   * Check if this is a front row (top 3 rows)
    80→   */
    81→  isFrontRow(rowRank: number): boolean {
    82→    return rowRank >= 1 && rowRank <= 3;
    83→  }
    84→
    85→  /**
    86→   * Estimate total rows in a section based on section tier
    87→   * Used when actual row count is unknown
    88→   */
    89→  estimateTotalRows(sectionTier: number): number {
    90→    // Common row counts by section type
    91→    const estimates: Record<number, number> = {
    92→      1: 20, // Premium (floor, VIP) - often smaller
    93→      2: 30, // Lower bowl
    94→      3: 25, // Mid level
    95→      4: 20, // Upper level
    96→      5: 15, // Obstructed/gallery
    97→    };
    98→
    99→    return estimates[sectionTier] ?? 25;
   100→  }
   101→}
