     1→/**
     2→ * Section Ranker
     3→ * Evaluates section quality based on venue data
     4→ */
     5→
     6→import { SectionTier } from '../value-score.types.js';
     7→
     8→// ============================================================================
     9→// Section Ranker
    10→// ============================================================================
    11→
    12→export class SectionRanker {
    13→  /**
    14→   * Convert section tier to score (0-100)
    15→   *
    16→   * Tier mapping:
    17→   * - PREMIUM (1) → 100
    18→   * - UPPER_PREMIUM (2) → 80
    19→   * - MID_TIER (3) → 60
    20→   * - UPPER_LEVEL (4) → 40
    21→   * - OBSTRUCTED (5) → 20
    22→   */
    23→  rank(tier: SectionTier): number {
    24→    const tierScores: Record<SectionTier, number> = {
    25→      [SectionTier.PREMIUM]: 100,
    26→      [SectionTier.UPPER_PREMIUM]: 80,
    27→      [SectionTier.MID_TIER]: 60,
    28→      [SectionTier.UPPER_LEVEL]: 40,
    29→      [SectionTier.OBSTRUCTED]: 20,
    30→    };
    31→
    32→    return tierScores[tier] ?? 50; // Default to mid score if unknown
    33→  }
    34→
    35→  /**
    36→   * Determine section tier from section name using venue data
    37→   */
    38→  getTierFromSectionName(
    39→    sectionName: string,
    40→    sectionTiers: Record<string, number>
    41→  ): SectionTier {
    42→    // Normalize section name for lookup
    43→    const normalized = this.normalizeSectionName(sectionName);
    44→
    45→    // Direct match
    46→    if (sectionTiers[sectionName] !== undefined) {
    47→      return sectionTiers[sectionName] as SectionTier;
    48→    }
    49→
    50→    // Normalized match
    51→    if (sectionTiers[normalized] !== undefined) {
    52→      return sectionTiers[normalized] as SectionTier;
    53→    }
    54→
    55→    // Partial match (e.g., "Section 102" → "102")
    56→    const numericPart = sectionName.replace(/\D/g, '');
    57→    if (numericPart && sectionTiers[numericPart] !== undefined) {
    58→      return sectionTiers[numericPart] as SectionTier;
    59→    }
    60→
    61→    // Heuristic fallback based on common patterns
    62→    return this.inferTierFromName(sectionName);
    63→  }
    64→
    65→  /**
    66→   * Check if a section is premium tier (1 or 2)
    67→   */
    68→  isPremiumSection(tier: SectionTier): boolean {
    69→    return tier === SectionTier.PREMIUM || tier === SectionTier.UPPER_PREMIUM;
    70→  }
    71→
    72→  // ==========================================================================
    73→  // Private Helpers
    74→  // ==========================================================================
    75→
    76→  /**
    77→   * Normalize section name for consistent lookup
    78→   */
    79→  private normalizeSectionName(name: string): string {
    80→    return name
    81→      .trim()
    82→      .toUpperCase()
    83→      .replace(/\s+/g, ' ')
    84→      .replace(/SECTION\s*/i, '')
    85→      .replace(/SEC\s*/i, '');
    86→  }
    87→
    88→  /**
    89→   * Infer tier from section name patterns when venue data unavailable
    90→   */
    91→  private inferTierFromName(name: string): SectionTier {
    92→    const lower = name.toLowerCase();
    93→
    94→    // Premium indicators
    95→    if (
    96→      lower.includes('floor') ||
    97→      lower.includes('pit') ||
    98→      lower.includes('vip') ||
    99→      lower.includes('club') ||
   100→      lower.includes('courtside') ||
   101→      lower.includes('field') ||
   102→      lower.includes('diamond')
   103→    ) {
   104→      return SectionTier.PREMIUM;
   105→    }
   106→
   107→    // Upper premium indicators
   108→    if (
   109→      lower.includes('lower') ||
   110→      lower.includes('terrace') ||
   111→      lower.includes('box')
   112→    ) {
   113→      return SectionTier.UPPER_PREMIUM;
   114→    }
   115→
   116→    // Upper level indicators
   117→    if (
   118→      lower.includes('upper') ||
   119→      lower.includes('balcony') ||
   120→      lower.includes('gallery') ||
   121→      lower.includes('mezzanine')
   122→    ) {
   123→      return SectionTier.UPPER_LEVEL;
   124→    }
   125→
   126→    // Obstructed indicators
   127→    if (
   128→      lower.includes('obstructed') ||
   129→      lower.includes('limited') ||
   130→      lower.includes('partial') ||
   131→      lower.includes('behind')
   132→    ) {
   133→      return SectionTier.OBSTRUCTED;
   134→    }
   135→
   136→    // Numeric section heuristics
   137→    const numericMatch = name.match(/(\d+)/);
   138→    if (numericMatch) {
   139→      const num = parseInt(numericMatch[1], 10);
   140→
   141→      // Common arena patterns: 100s = lower, 200s = mid, 300s = upper
   142→      if (num >= 100 && num < 200) return SectionTier.UPPER_PREMIUM;
   143→      if (num >= 200 && num < 300) return SectionTier.MID_TIER;
   144→      if (num >= 300) return SectionTier.UPPER_LEVEL;
   145→    }
   146→
   147→    // Default to mid-tier
   148→    return SectionTier.MID_TIER;
   149→  }
   150→}
