     1→/**
     2→ * Deep Link Generator
     3→ * Generates platform-specific purchase links for ticket listings
     4→ */
     5→
     6→import type { Platform } from '../adapters/base/platform-adapter.interface.js';
     7→
     8→interface DeepLinkParams {
     9→  platform: Platform;
    10→  eventId: string;
    11→  listingId: string;
    12→  quantity?: number;
    13→}
    14→
    15→/**
    16→ * Generate a deep link to the purchase page for a listing
    17→ */
    18→export function generateDeepLink(params: DeepLinkParams): string {
    19→  const { platform, eventId, listingId, quantity } = params;
    20→
    21→  switch (platform) {
    22→    case 'stubhub':
    23→      return generateStubHubLink(eventId, listingId, quantity);
    24→
    25→    case 'ticketmaster':
    26→      return generateTicketmasterLink(eventId, listingId);
    27→
    28→    case 'seatgeek':
    29→      return generateSeatGeekLink(eventId, listingId);
    30→
    31→    case 'vividseats':
    32→      return generateVividSeatsLink(eventId, listingId);
    33→
    34→    default:
    35→      throw new Error(`Unknown platform: ${platform}`);
    36→  }
    37→}
    38→
    39→/**
    40→ * StubHub deep link
    41→ * Format: https://www.stubhub.com/event/{eventId}/?ticket={listingId}&qty={quantity}
    42→ */
    43→function generateStubHubLink(eventId: string, listingId: string, quantity?: number): string {
    44→  const baseUrl = `https://www.stubhub.com/event/${eventId}/`;
    45→  const params = new URLSearchParams({
    46→    ticket: listingId,
    47→  });
    48→
    49→  if (quantity) {
    50→    params.set('qty', quantity.toString());
    51→  }
    52→
    53→  return `${baseUrl}?${params.toString()}`;
    54→}
    55→
    56→/**
    57→ * Ticketmaster deep link
    58→ * Format: https://www.ticketmaster.com/event/{eventId}?listingId={listingId}
    59→ */
    60→function generateTicketmasterLink(eventId: string, listingId: string): string {
    61→  const baseUrl = `https://www.ticketmaster.com/event/${eventId}`;
    62→  const params = new URLSearchParams({
    63→    listingId,
    64→  });
    65→
    66→  return `${baseUrl}?${params.toString()}`;
    67→}
    68→
    69→/**
    70→ * SeatGeek deep link
    71→ * Format: https://seatgeek.com/checkout/{eventId}/{listingId}
    72→ */
    73→function generateSeatGeekLink(eventId: string, listingId: string): string {
    74→  return `https://seatgeek.com/checkout/${eventId}/${listingId}`;
    75→}
    76→
    77→/**
    78→ * Vivid Seats deep link
    79→ * Format: https://www.vividseats.com/checkout?productionId={eventId}&ticketId={listingId}
    80→ */
    81→function generateVividSeatsLink(eventId: string, listingId: string): string {
    82→  const params = new URLSearchParams({
    83→    productionId: eventId,
    84→    ticketId: listingId,
    85→  });
    86→
    87→  return `https://www.vividseats.com/checkout?${params.toString()}`;
    88→}
    89→
    90→/**
    91→ * Validate that a deep link is properly formatted
    92→ */
    93→export function validateDeepLink(link: string): boolean {
    94→  try {
    95→    const url = new URL(link);
    96→    const validHosts = [
    97→      'www.stubhub.com',
    98→      'stubhub.com',
    99→      'www.ticketmaster.com',
   100→      'ticketmaster.com',
   101→      'seatgeek.com',
   102→      'www.seatgeek.com',
   103→      'www.vividseats.com',
   104→      'vividseats.com',
   105→    ];
   106→
   107→    return validHosts.includes(url.hostname);
   108→  } catch {
   109→    return false;
   110→  }
   111→}
   112→
   113→/**
   114→ * Extract platform from a deep link URL
   115→ */
   116→export function extractPlatformFromLink(link: string): Platform | null {
   117→  try {
   118→    const url = new URL(link);
   119→    const host = url.hostname.replace('www.', '');
   120→
   121→    if (host.includes('stubhub')) return 'stubhub';
   122→    if (host.includes('ticketmaster')) return 'ticketmaster';
   123→    if (host.includes('seatgeek')) return 'seatgeek';
   124→    if (host.includes('vividseats')) return 'vividseats';
   125→
   126→    return null;
   127→  } catch {
   128→    return null;
   129→  }
   130→}
