     1→/**
     2→ * Rate Limiter Utility
     3→ * Token bucket implementation for API rate limiting
     4→ */
     5→
     6→interface RateLimiterConfig {
     7→  /** Number of tokens added per interval */
     8→  tokensPerInterval: number;
     9→
    10→  /** Interval type */
    11→  interval: 'second' | 'minute' | 'hour' | 'day';
    12→
    13→  /** Maximum tokens that can be stored (burst capacity) */
    14→  maxTokens?: number;
    15→}
    16→
    17→const INTERVAL_MS: Record<string, number> = {
    18→  second: 1000,
    19→  minute: 60 * 1000,
    20→  hour: 60 * 60 * 1000,
    21→  day: 24 * 60 * 60 * 1000,
    22→};
    23→
    24→export class RateLimiter {
    25→  private tokens: number;
    26→  private maxTokens: number;
    27→  private tokensPerInterval: number;
    28→  private intervalMs: number;
    29→  private lastRefill: number;
    30→  private waitQueue: Array<() => void> = [];
    31→
    32→  constructor(config: RateLimiterConfig) {
    33→    this.tokensPerInterval = config.tokensPerInterval;
    34→    this.maxTokens = config.maxTokens ?? config.tokensPerInterval;
    35→    this.intervalMs = INTERVAL_MS[config.interval];
    36→    this.tokens = this.maxTokens;
    37→    this.lastRefill = Date.now();
    38→  }
    39→
    40→  /**
    41→   * Refill tokens based on elapsed time
    42→   */
    43→  private refill(): void {
    44→    const now = Date.now();
    45→    const elapsed = now - this.lastRefill;
    46→    const refillAmount = (elapsed / this.intervalMs) * this.tokensPerInterval;
    47→
    48→    this.tokens = Math.min(this.maxTokens, this.tokens + refillAmount);
    49→    this.lastRefill = now;
    50→  }
    51→
    52→  /**
    53→   * Try to acquire a token immediately
    54→   * @returns true if token was acquired, false otherwise
    55→   */
    56→  tryAcquire(): boolean {
    57→    this.refill();
    58→
    59→    if (this.tokens >= 1) {
    60→      this.tokens -= 1;
    61→      return true;
    62→    }
    63→
    64→    return false;
    65→  }
    66→
    67→  /**
    68→   * Acquire a token, waiting if necessary
    69→   * @returns Promise that resolves when token is acquired
    70→   */
    71→  async acquire(): Promise<void> {
    72→    if (this.tryAcquire()) {
    73→      return;
    74→    }
    75→
    76→    // Calculate wait time until next token
    77→    const tokensNeeded = 1 - this.tokens;
    78→    const waitTime = (tokensNeeded / this.tokensPerInterval) * this.intervalMs;
    79→
    80→    return new Promise<void>((resolve) => {
    81→      setTimeout(() => {
    82→        this.refill();
    83→        this.tokens -= 1;
    84→        resolve();
    85→        this.processQueue();
    86→      }, waitTime);
    87→    });
    88→  }
    89→
    90→  /**
    91→   * Process any waiting requests
    92→   */
    93→  private processQueue(): void {
    94→    while (this.waitQueue.length > 0 && this.tryAcquire()) {
    95→      const next = this.waitQueue.shift();
    96→      next?.();
    97→    }
    98→  }
    99→
   100→  /**
   101→   * Get current token count
   102→   */
   103→  getAvailableTokens(): number {
   104→    this.refill();
   105→    return Math.floor(this.tokens);
   106→  }
   107→
   108→  /**
   109→   * Get estimated wait time for next token (in ms)
   110→   */
   111→  getWaitTime(): number {
   112→    this.refill();
   113→
   114→    if (this.tokens >= 1) {
   115→      return 0;
   116→    }
   117→
   118→    const tokensNeeded = 1 - this.tokens;
   119→    return (tokensNeeded / this.tokensPerInterval) * this.intervalMs;
   120→  }
   121→}
   122→
   123→/**
   124→ * Create a rate limiter from requests per day
   125→ */
   126→export function createDailyRateLimiter(requestsPerDay: number): RateLimiter {
   127→  // Convert to requests per minute for smoother distribution
   128→  const requestsPerMinute = Math.max(1, Math.floor(requestsPerDay / (24 * 60)));
   129→
   130→  return new RateLimiter({
   131→    tokensPerInterval: requestsPerMinute,
   132→    interval: 'minute',
   133→    maxTokens: Math.min(requestsPerMinute * 5, 50), // Allow some burst
   134→  });
   135→}
   136→
   137→/**
   138→ * Create a rate limiter from requests per minute
   139→ */
   140→export function createMinuteRateLimiter(requestsPerMinute: number): RateLimiter {
   141→  return new RateLimiter({
   142→    tokensPerInterval: requestsPerMinute,
   143→    interval: 'minute',
   144→    maxTokens: requestsPerMinute,
   145→  });
   146→}
