     1→/**
     2→ * Seat Map Service
     3→ * Handles loading venue seat maps from APIs (Ticketmaster, SeatGeek) and local fallbacks
     4→ */
     5→
     6→import sharp from 'sharp';
     7→import axios from 'axios';
     8→import path from 'path';
     9→import { fileURLToPath } from 'url';
    10→import type {
    11→  VenueSeatMap,
    12→  SectionPolygon,
    13→  HighlightOptions,
    14→  SeatMapRegistry,
    15→} from './seat-map.types.js';
    16→import { DEFAULT_HIGHLIGHT_OPTIONS } from './seat-map.types.js';
    17→import { VENUE_SEAT_MAPS } from './seat-map.registry.js';
    18→import { logger } from '../utils/logger.js';
    19→
    20→// Get directory path for ESM
    21→const __filename = fileURLToPath(import.meta.url);
    22→const __dirname = path.dirname(__filename);
    23→
    24→// ============================================================================
    25→// Seat Map Service
    26→// ============================================================================
    27→
    28→export class SeatMapService {
    29→  private registry: SeatMapRegistry;
    30→  private assetsPath: string;
    31→  private urlCache: Map<string, Buffer> = new Map();
    32→
    33→  constructor() {
    34→    this.registry = VENUE_SEAT_MAPS;
    35→    this.assetsPath = path.join(__dirname, '../../assets/seat-maps');
    36→  }
    37→
    38→  // ==========================================================================
    39→  // Venue Lookup
    40→  // ==========================================================================
    41→
    42→  /**
    43→   * Find a venue seat map by name (fuzzy matching)
    44→   */
    45→  findVenue(venueName: string): VenueSeatMap | undefined {
    46→    const normalizedSearch = this.normalizeVenueName(venueName);
    47→
    48→    // Try exact match first
    49→    if (this.registry.has(normalizedSearch)) {
    50→      return this.registry.get(normalizedSearch);
    51→    }
    52→
    53→    // Try partial match
    54→    for (const [key, seatMap] of this.registry) {
    55→      if (key.includes(normalizedSearch) || normalizedSearch.includes(key)) {
    56→        return seatMap;
    57→      }
    58→    }
    59→
    60→    // Try matching by venue name in the map
    61→    for (const seatMap of this.registry.values()) {
    62→      const normalizedMapName = this.normalizeVenueName(seatMap.venueName);
    63→      if (
    64→        normalizedMapName.includes(normalizedSearch) ||
    65→        normalizedSearch.includes(normalizedMapName)
    66→      ) {
    67→        return seatMap;
    68→      }
    69→    }
    70→
    71→    return undefined;
    72→  }
    73→
    74→  /**
    75→   * Get all available venues
    76→   */
    77→  getAvailableVenues(): string[] {
    78→    return Array.from(this.registry.values()).map(v => v.venueName);
    79→  }
    80→
    81→  /**
    82→   * Check if a venue has a seat map
    83→   */
    84→  hasVenue(venueName: string): boolean {
    85→    return this.findVenue(venueName) !== undefined;
    86→  }
    87→
    88→  // ==========================================================================
    89→  // Section Lookup
    90→  // ==========================================================================
    91→
    92→  /**
    93→   * Find a section polygon by section name/number
    94→   */
    95→  findSection(venue: VenueSeatMap, sectionName: string): SectionPolygon | undefined {
    96→    const normalizedSection = sectionName.toLowerCase().trim();
    97→
    98→    // Try exact match
    99→    let section = venue.sections.find(
   100→      s => s.sectionId.toLowerCase() === normalizedSection ||
   101→           s.sectionName.toLowerCase() === normalizedSection
   102→    );
   103→
   104→    if (section) return section;
   105→
   106→    // Try partial match (e.g., "112" matches "Section 112")
   107→    section = venue.sections.find(
   108→      s => s.sectionId.includes(normalizedSection) ||
   109→           s.sectionName.toLowerCase().includes(normalizedSection) ||
   110→           normalizedSection.includes(s.sectionId)
   111→    );
   112→
   113→    return section;
   114→  }
   115→
   116→  // ==========================================================================
   117→  // Image Generation
   118→  // ==========================================================================
   119→
   120→  /**
   121→   * Generate a seat map image with highlighted section
   122→   */
   123→  async generateHighlightedMap(
   124→    venueName: string,
   125→    sectionName: string,
   126→    options: Partial<HighlightOptions> = {}
   127→  ): Promise<Buffer | null> {
   128→    const venue = this.findVenue(venueName);
   129→    if (!venue) {
   130→      logger.warn(`[SeatMap] Venue not found: ${venueName}`);
   131→      return null;
   132→    }
   133→
   134→    const section = this.findSection(venue, sectionName);
   135→    if (!section) {
   136→      logger.warn(`[SeatMap] Section not found: ${sectionName} at ${venueName}`);
   137→      // Return base image without highlighting
   138→      return this.getBaseImage(venue);
   139→    }
   140→
   141→    const mergedOptions = { ...DEFAULT_HIGHLIGHT_OPTIONS, ...options };
   142→
   143→    try {
   144→      const imagePath = path.join(this.assetsPath, venue.imageFile);
   145→
   146→      // Create SVG overlay for the highlight
   147→      const svg = this.createHighlightSvg(
   148→        section,
   149→        venue.imageWidth,
   150→        venue.imageHeight,
   151→        mergedOptions
   152→      );
   153→
   154→      // Composite the highlight onto the base image
   155→      const highlightedImage = await sharp(imagePath)
   156→        .composite([{
   157→          input: Buffer.from(svg),
   158→          top: 0,
   159→          left: 0,
   160→        }])
   161→        .jpeg({ quality: 85 })
   162→        .toBuffer();
   163→
   164→      logger.info(`[SeatMap] Generated highlighted map for ${venueName} section ${sectionName}`);
   165→      return highlightedImage;
   166→    } catch (error) {
   167→      logger.error(`[SeatMap] Failed to generate highlighted map`, {
   168→        venue: venueName,
   169→        section: sectionName,
   170→        error: error instanceof Error ? error.message : 'Unknown error',
   171→      });
   172→      return null;
   173→    }
   174→  }
   175→
   176→  /**
   177→   * Get the base seat map image without highlighting
   178→   */
   179→  async getBaseImage(venue: VenueSeatMap): Promise<Buffer | null> {
   180→    try {
   181→      const imagePath = path.join(this.assetsPath, venue.imageFile);
   182→      return await sharp(imagePath).jpeg({ quality: 85 }).toBuffer();
   183→    } catch (error) {
   184→      logger.error(`[SeatMap] Failed to load base image for ${venue.venueName}`);
   185→      return null;
   186→    }
   187→  }
   188→
   189→  /**
   190→   * Generate a multi-section highlighted map (for showing multiple deals)
   191→   */
   192→  async generateMultiHighlightMap(
   193→    venueName: string,
   194→    sections: Array<{ sectionName: string; rank: number }>
   195→  ): Promise<Buffer | null> {
   196→    const venue = this.findVenue(venueName);
   197→    if (!venue) {
   198→      logger.warn(`[SeatMap] Venue not found: ${venueName}`);
   199→      return null;
   200→    }
   201→
   202→    try {
   203→      const imagePath = path.join(this.assetsPath, venue.imageFile);
   204→
   205→      // Create SVG overlays for all sections
   206→      const svgParts: string[] = [];
   207→
   208→      for (const { sectionName, rank } of sections) {
   209→        const section = this.findSection(venue, sectionName);
   210→        if (!section) continue;
   211→
   212→        // Different colors for different ranks
   213→        const color = this.getRankColor(rank);
   214→        svgParts.push(this.createSectionPath(section, color, rank));
   215→      }
   216→
   217→      if (svgParts.length === 0) {
   218→        return this.getBaseImage(venue);
   219→      }
   220→
   221→      const svg = `<svg width="${venue.imageWidth}" height="${venue.imageHeight}" xmlns="http://www.w3.org/2000/svg">
   222→        ${svgParts.join('\n')}
   223→      </svg>`;
   224→
   225→      const highlightedImage = await sharp(imagePath)
   226→        .composite([{
   227→          input: Buffer.from(svg),
   228→          top: 0,
   229→          left: 0,
   230→        }])
   231→        .jpeg({ quality: 85 })
   232→        .toBuffer();
   233→
   234→      logger.info(`[SeatMap] Generated multi-highlight map for ${venueName} with ${sections.length} sections`);
   235→      return highlightedImage;
   236→    } catch (error) {
   237→      logger.error(`[SeatMap] Failed to generate multi-highlight map`, {
   238→        venue: venueName,
   239→        error: error instanceof Error ? error.message : 'Unknown error',
   240→      });
   241→      return null;
   242→    }
   243→  }
   244→
   245→  // ==========================================================================
   246→  // SVG Generation Helpers
   247→  // ==========================================================================
   248→
   249→  /**
   250→   * Create an SVG for highlighting a section
   251→   */
   252→  private createHighlightSvg(
   253→    section: SectionPolygon,
   254→    width: number,
   255→    height: number,
   256→    options: HighlightOptions
   257→  ): string {
   258→    const pathD = this.pointsToSvgPath(section.points);
   259→    const { fillColor, strokeColor, strokeWidth, showLabel, labelText } = options;
   260→
   261→    const fillRgba = `rgba(${fillColor.r}, ${fillColor.g}, ${fillColor.b}, ${fillColor.a})`;
   262→    const strokeRgb = `rgb(${strokeColor.r}, ${strokeColor.g}, ${strokeColor.b})`;
   263→
   264→    let labelSvg = '';
   265→    if (showLabel) {
   266→      const text = labelText || section.sectionName;
   267→      labelSvg = `
   268→        <text
   269→          x="${section.center.x}"
