  ? totalPrice.value / quantity  // Assumes 'total' is for all tickets
  : facePrice?.value || 0;       // Assumes 'face' is per ticket

// FIX: Clarify semantics and handle edge cases:
const pricePerTicket = facePrice?.value
  ?? (totalPrice ? totalPrice.value / quantity : 0);
// Prefer face value (always per ticket), fall back to total/qty
```

